const a=JSON.parse('{"workId":"cai-gen-tan","chapter":{"id":"cai-gen-tan_ch-1","workId":"cai-gen-tan","order":1,"title":"修身","difficulty":3,"estimatedMinutes":54,"passageIds":["cai-gen-tan_ch-1_p-1","cai-gen-tan_ch-1_p-2","cai-gen-tan_ch-1_p-3","cai-gen-tan_ch-1_p-4","cai-gen-tan_ch-1_p-5","cai-gen-tan_ch-1_p-6","cai-gen-tan_ch-1_p-7","cai-gen-tan_ch-1_p-8","cai-gen-tan_ch-1_p-9","cai-gen-tan_ch-1_p-10","cai-gen-tan_ch-1_p-11","cai-gen-tan_ch-1_p-12","cai-gen-tan_ch-1_p-13","cai-gen-tan_ch-1_p-14","cai-gen-tan_ch-1_p-15","cai-gen-tan_ch-1_p-16","cai-gen-tan_ch-1_p-17","cai-gen-tan_ch-1_p-18","cai-gen-tan_ch-1_p-19","cai-gen-tan_ch-1_p-20","cai-gen-tan_ch-1_p-21","cai-gen-tan_ch-1_p-22","cai-gen-tan_ch-1_p-23","cai-gen-tan_ch-1_p-24","cai-gen-tan_ch-1_p-25","cai-gen-tan_ch-1_p-26","cai-gen-tan_ch-1_p-27","cai-gen-tan_ch-1_p-28","cai-gen-tan_ch-1_p-29","cai-gen-tan_ch-1_p-30","cai-gen-tan_ch-1_p-31","cai-gen-tan_ch-1_p-32","cai-gen-tan_ch-1_p-33","cai-gen-tan_ch-1_p-34","cai-gen-tan_ch-1_p-35","cai-gen-tan_ch-1_p-36","cai-gen-tan_ch-1_p-37","cai-gen-tan_ch-1_p-38","cai-gen-tan_ch-1_p-39","cai-gen-tan_ch-1_p-40","cai-gen-tan_ch-1_p-41","cai-gen-tan_ch-1_p-42","cai-gen-tan_ch-1_p-43","cai-gen-tan_ch-1_p-44","cai-gen-tan_ch-1_p-45","cai-gen-tan_ch-1_p-46","cai-gen-tan_ch-1_p-47","cai-gen-tan_ch-1_p-48","cai-gen-tan_ch-1_p-49","cai-gen-tan_ch-1_p-50","cai-gen-tan_ch-1_p-51","cai-gen-tan_ch-1_p-52","cai-gen-tan_ch-1_p-53","cai-gen-tan_ch-1_p-54","cai-gen-tan_ch-1_p-55","cai-gen-tan_ch-1_p-56","cai-gen-tan_ch-1_p-57","cai-gen-tan_ch-1_p-58","cai-gen-tan_ch-1_p-59","cai-gen-tan_ch-1_p-60","cai-gen-tan_ch-1_p-61","cai-gen-tan_ch-1_p-62","cai-gen-tan_ch-1_p-63","cai-gen-tan_ch-1_p-64","cai-gen-tan_ch-1_p-65","cai-gen-tan_ch-1_p-66","cai-gen-tan_ch-1_p-67","cai-gen-tan_ch-1_p-68","cai-gen-tan_ch-1_p-69","cai-gen-tan_ch-1_p-70","cai-gen-tan_ch-1_p-71","cai-gen-tan_ch-1_p-72","cai-gen-tan_ch-1_p-73"],"tags":["文學","處世","修身"]},"passages":[{"id":"cai-gen-tan_ch-1_p-1","chapterId":"cai-gen-tan_ch-1","order":1,"canonicalText":"餘過古剎，於殘經敗紙中拾得《菜根譚》一錄。翻視之，雖屬禪宗，然於身心性命之學，實有隱隱相發明者。亟攜歸，重加校讎，繕寫成帙。舊有序，文不雅馴，且於是書無關涉語，故芟之。著是書者為洪應明，究不知其為何許人也。","sentenceIds":["cai-gen-tan_ch-1_p-1_s-1","cai-gen-tan_ch-1_p-1_s-2","cai-gen-tan_ch-1_p-1_s-3","cai-gen-tan_ch-1_p-1_s-4","cai-gen-tan_ch-1_p-1_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"我路過一座古老的寺廟，在殘存的佛經和破爛的紙張中，撿到了一本名為《菜根譚》的記錄。翻開閱讀它，雖然這本書的內容偏向禪宗，但是對於調養身心、安頓性命的學問，實在有隱約相互啟發、闡明之處。我急忙帶回家，重新加以校勘核對，繕寫裝訂成冊。舊有的序言文筆不夠雅緻順暢，而且與這本書的內容沒什麼關係，所以把它刪除了。寫這本書的人是洪應明，但究竟不知道他是個什麼樣的人。","analysis":"【主題與背景】本段為《菜根譚》的序言，說明瞭此書的發現經過、內容性質以及版本整理的過程。撰序者（遂初堂主人）指出，此書雖有禪宗色彩，但實則融會貫通了儒釋道三家關於「身心性命之學」的智慧，具有相互發明、印證的價值。\\\\n【詞義與名物】「菜根」之名源自宋代汪信民所言「人咬得菜根，百事可做」，意指能夠忍受清苦、耐得淡泊，方能成就學問與事業。\\\\n【思想與篇章】序中提到原作者為明代學者洪應明（字自誠），但其生平不詳，反映出此書在當時屬於民間流傳的警世格言集，經過後人整理校讎後才得以傳世。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-2","chapterId":"cai-gen-tan_ch-1","order":2,"canonicalText":"乾隆五十九年二月二日，遂初堂主人識","sentenceIds":["cai-gen-tan_ch-1_p-2_s-1"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大清乾隆五十九年（西元1794年）農曆二月初二日，遂初堂主人洪應明恭敬題記於此。","analysis":"【主旨】此為《菜根譚》全書卷首題款落款，標誌著明代洪應明著述、清乾隆甲寅重刊之重要版本定型，確立了全書流傳後世的權威刻印源流。\\n【詞義】「遂初堂」作者洪應明的書齋堂號，典出東晉孫綽《遂初賦》，寓意退隱田園、遂其初願之高潔志向；「識」題記、署名之意（音志，古通誌）。\\n【版本考證】乾隆五十九年（1794年）歲在甲寅，遂初堂刻本為現存《菜根譚》流傳最廣、校勘最稱精善的祖本之一。\\n【思想價值】《菜根譚》融通儒釋道三教精華，作者於卷首題識自表退隱守真之心，為全書修身處世的安詳智慧奠定了崇高的精神基調。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-3","chapterId":"cai-gen-tan_ch-1","order":3,"canonicalText":"欲做精金美玉的人品，定從烈火中煆來；思立掀天揭地的事功，須向薄冰上履過。","sentenceIds":["cai-gen-tan_ch-1_p-3_s-1","cai-gen-tan_ch-1_p-3_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"想要鍛鍊出如精金美玉般高尚純潔的人格品質，必定要從烈火般的艱難困苦中磨練出來；想要建立驚天動地的偉大功業，必須像走在薄冰上那樣，時刻保持謹慎戒懼的態度。","analysis":"【主題與背景】本條闡述修身與立業的辯證關係，融合了儒家的憂患意識與磨練思想。「精金美玉」喻指完美無瑕的品德，非經「烈火」之煆燒（象徵逆境與挫折的考驗）不能去其雜質，這與孟子「天將降大任於是人也，必先苦其心志」的思想相通。\\\\n【詞義與名物】「掀天揭地」指極大的功業，而「薄冰上履」則典出《詩經·小雅·小旻》的「戰戰兢兢，如臨深淵，如履薄冰」，強調越是在成就大事的過程中，越需要有敬畏之心與如履薄冰的審慎態度，如此方能防微杜漸，行穩致遠。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-4","chapterId":"cai-gen-tan_ch-1","order":4,"canonicalText":"一念錯，便覺百行皆非，防之當如渡海浮囊，勿容一針之罅漏；萬善全，始得一生無愧。修之當如凌雲寶樹，須假眾木以撐持。","sentenceIds":["cai-gen-tan_ch-1_p-4_s-1","cai-gen-tan_ch-1_p-4_s-2","cai-gen-tan_ch-1_p-4_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一個念頭出差錯，就會讓人覺得所有的行為都有了汙點，防範惡念應當像攜帶渡海的救生浮囊一樣，絕不容許有針尖般大小的裂縫漏氣；萬種善行都齊備，才能做到一生問心無愧，修養德行應當像高聳入雲的寶樹一樣，必須藉助眾多樹木的相互支撐扶持。","analysis":"【主題與背景】此段強調修身防惡之嚴密與行善積德之宏闊。「防之當如渡海浮囊」是借喻，佛教和道家常以「渡海」比喻超脫生死苦海，浮囊（救生皮袋）若有「一針之罅漏」（微小的裂縫）便會漏氣沉沒，比喻在道德修養上，哪怕是極其微小的一個惡念，也能敗壞一生的操守，必須防微杜漸。\\\\n【詞義與名物】「凌雲寶樹，須假眾木以撐持」則說明為善修德不是孤立的，需要廣積善行、藉助眾人與萬物的力量，也寓意個人修身需要良好的環境與志同道合者的相互砥礪。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-5","chapterId":"cai-gen-tan_ch-1","order":5,"canonicalText":"忙處事為，常向閒中先檢點，過舉自稀。動時念想，預從靜裏密操持，非心自息。","sentenceIds":["cai-gen-tan_ch-1_p-5_s-1","cai-gen-tan_ch-1_p-5_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"忙碌時所要處理的事務，如果經常在清閒時就預先仔細檢查與計畫，那麼出錯的舉動自然就會減少。活動時所產生的意念和想法，如果預先在安靜時就暗中修持與控制，那麼不合正道的邪念自然就會平息。","analysis":"【訓詁與名物】「忙處」指繁忙之時；「事為」指所做的事情與行動。「檢點」為查覈、反省之意。「過舉」即過失的舉動。「密」有暗中、嚴密之意；「操持」指控制、把持。「非心」即不符合正理的非分之想與邪念。\\\\n【章法與結構】本段採取對偶句法，「忙處事為」對「動時念想」，「常向閒中先檢點」對「預從靜裏密操持」，「過舉自稀」對「非心自息」。動靜對比，文句整飭，強調防患未然的修身之道。\\\\n【思想與義理】此句點出「動靜相養」的哲理，主張在事物尚未發生或心念尚未起伏的「閒」與「靜」之際，便要做好反省與修持。這種「治未病」的功夫，不僅適用於外在事物的處理，更適用於內在心靈的涵養，教導人在平靜中積蓄力量以應對紛繁的世界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-6","chapterId":"cai-gen-tan_ch-1","order":6,"canonicalText":"為善而欲自高勝人，施恩而欲要名結好，修業而欲驚世駭俗，植節而欲標異見奇，此皆是善念中戈矛，理路上荊棘，最易夾帶，最難拔除者也。須是滌盡渣滓，斬絕萌芽，纔見本來真體。","sentenceIds":["cai-gen-tan_ch-1_p-6_s-1","cai-gen-tan_ch-1_p-6_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"做善事卻想要抬高自己、超越他人，施予恩惠卻想要索取名譽、結交討好，建立事業卻想要驚世駭俗，樹立節操卻想要標新立異、顯露奇特，這些都是善良心念中隱藏的戈矛，追求真理道路上的荊棘，最容易暗中夾帶，也最難以拔除。必須徹底洗滌乾淨這些雜質，斬斷這些不良動機的萌芽，才能顯現出本性中純真無瑕的本體。","analysis":"【主題與背景】此段深刻剖析了虛偽之善與動機不純的危害。「為善」、「施恩」、「修業」、「植節」本是美德，但若摻雜了「自高勝人」、「要名結好」、「驚世駭俗」、「標異見奇」等名利心與好勝心，美德便異化為「戈矛」與「荊棘」，反過來傷害自身、阻礙道業。\\\\n【詞義與名物】這符合佛教關於「三輪體空」（施者、受者、施物皆空，不著相施恩）與禪宗「無相佈施」的思想，亦與老子「上德不德，是以有德」的觀念相通。\\\\n【思想與篇章】只有滌盡名利渣滓，才能恢復儒家所謂的「本心」或佛教的「自性真如」（本來真體）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-7","chapterId":"cai-gen-tan_ch-1","order":7,"canonicalText":"能輕富貴，不能輕一輕富貴之心；能重名義，又復重一重名義之念。是事境之塵氛未掃，而心境之芥蒂未忘。此處拔除不凈，恐石去而草復生矣。","sentenceIds":["cai-gen-tan_ch-1_p-7_s-1","cai-gen-tan_ch-1_p-7_s-2","cai-gen-tan_ch-1_p-7_s-3","cai-gen-tan_ch-1_p-7_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"能夠看輕財富與地位，卻無法放下那種「看輕富貴」的自傲心態；能夠看重名譽與道義，卻又反過來執著於那種「看重名義」的念頭。這表示外在環境所帶來的世俗塵垢尚未完全掃除，而內心的微小執念依然存在。如果在這些細微處不能清除乾淨，恐怕就像搬走石頭後，雜草依然會重新生長出來。","analysis":"【訓詁與名物】「輕」作動詞，看輕；「輕一輕富貴之心」指自詡能夠看輕富貴的那份執著心態。「重」為看重；「名義」即名節道義。「事境」指外在的事物與環境；「塵氛」比喻世俗的煩惱。「芥蒂」本指梗塞於喉胸之物，此喻內心的疙瘩與執念。「石去而草復生」比喻病根未除，稍有機會便會死灰復燃。\\\\n【章法與結構】前兩句「能輕...不能輕...；能重...又復重...」構成對比與遞進，點出表面與深層修養的差異。接著以「是事境之...而心境之...」作總結，最後以「石去而草復生」的生動譬喻收尾，層次分明，發人深省。\\\\n【思想與義理】本文探討了修養的深層境界。破除對名利的執著固然重要，但若因此產生了「我能破除執著」的驕傲與執念，則依然落入另一種精神的枷鎖。真正的超脫，是既不執著於世俗名利，也不標榜自己的清高，達到所謂「忘機」、「無我」的澄明心境。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-8","chapterId":"cai-gen-tan_ch-1","order":8,"canonicalText":"紛擾固溺志之場，而枯寂亦槁心之地。故學者當棲心元默，以寧吾真體。亦當適志恬愉，以養吾圓機。","sentenceIds":["cai-gen-tan_ch-1_p-8_s-1","cai-gen-tan_ch-1_p-8_s-2","cai-gen-tan_ch-1_p-8_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"紛繁雜亂的塵世固然是沉溺志向、消磨意志的場所，但若一味追求枯槁沉寂，也會成為使心靈乾枯、喪失生機的地方。所以學習修身的人，應當將心靈寄託於玄妙靜默的境地，以安寧自己純真的本性；同時也應當使情志舒暢、怡然自得，以培養自己圓融靈活的生機。","analysis":"【主題與背景】此段提出了「中庸之道」與「理事圓融」的修身觀，反對走極端。外在的「紛擾」容易讓人迷失本心（溺志），但若為了逃避而走向極端的「枯寂」（如佛教所斥的「枯木禪」或過度消極的出世），則會使心靈失去活力（槁心）。\\\\n【詞義與名物】因此，修行者一方面要在「元默」（深沉安靜的本體）中安寧真體，另一方面又要在「恬愉」（安適喜悅）中涵養「圓機」（圓通靈活的生機、契機）。\\\\n【思想與篇章】這結合了道家的「自然」與儒家的「樂道」思想，強調動靜相兼、體用一源。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-9","chapterId":"cai-gen-tan_ch-1","order":9,"canonicalText":"昨日之非不可留，留之則根燼復萌，而塵情終累乎理趣；今日之是不可執，執之則渣滓未化，而理趣反轉為欲根。","sentenceIds":["cai-gen-tan_ch-1_p-9_s-1","cai-gen-tan_ch-1_p-9_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"昨日的過錯不能留在心中，如果留戀或耿耿於懷，那麼錯誤的根源和餘燼就會重新萌芽，而世俗的塵念終究會拖累高尚的真理趣向；今日的正確也不能死板執著，如果固執不化，那麼它就會變成未融化的雜質，而原本高尚的理趣反而會轉化為滋生私慾的根源。","analysis":"【主題與背景】本條闡述對「是」與「非」的超越，體現了禪宗「無住生心」與道家「損之又損」的修持方法。「昨日之非不可留」，意在勸人不要為過去的錯誤背負沉重的精神包袱，否則容易自暴自棄或重蹈覆轍，拖累了對天理的追求。\\\\n【詞義與名物】「今日之是不可執」，則是警告人們不要因當下的成就或正確而沾沾自喜、墨守成規，一旦對「是」產生執著，這種清高或自滿便會化為新的私欲（欲根），阻礙心靈的進一步昇華。\\\\n【思想與篇章】這要求修身者隨時清空心靈，保持如鏡照物、不留痕跡的澄明狀態。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-10","chapterId":"cai-gen-tan_ch-1","order":10,"canonicalText":"無事便思有閑雜念想否。有事便思有粗浮意氣否。得意便思有驕矜辭色否。失意便思有怨望情懷否。時時檢點，到得從多入少、從有入無處，纔是學問的真消息。","sentenceIds":["cai-gen-tan_ch-1_p-10_s-1","cai-gen-tan_ch-1_p-10_s-2","cai-gen-tan_ch-1_p-10_s-3","cai-gen-tan_ch-1_p-10_s-4","cai-gen-tan_ch-1_p-10_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"閒暇無事時，要反思自己是否有閒散雜亂的念頭；投身事務時，要反思自己是否有粗率浮躁的意氣；順心得意時，要反思自己是否有驕傲自滿的言辭神色；挫折失意時，要反思自己是否有怨天尤人的悲觀情懷。時時刻刻進行自我檢點，直到雜念與偏頗從多變少、從有到無的境地，這才是做學問達到的真實境界。","analysis":"【主題與背景】本條是一段非常具體且實用的儒家式自我省察工夫，類似於曾子的「吾日三省吾身」。作者從「無事、有事、得意、失意」四種人生常態切入，要求在不同情境下針對易犯的毛病（雜念、粗浮、驕矜、怨望）進行「時時檢點」。\\\\n【詞義與名物】最終的目標是達到「從多入少、從有入無」的境界，這與老子「為學日益，為道日損」相呼應。\\\\n【思想與篇章】「真消息」意指真實的契機、真諦，唯有通過持續不斷的減法工夫，才能逐漸接近心性的本源。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-11","chapterId":"cai-gen-tan_ch-1","order":11,"canonicalText":"士人有百折不回之真心，纔有萬變不窮之妙用。立業建功，事事要從實地著腳，若少慕聲聞，便成偽果；講道修德，念念要從虛處立基，若稍計功效，便落塵情。","sentenceIds":["cai-gen-tan_ch-1_p-11_s-1","cai-gen-tan_ch-1_p-11_s-2","cai-gen-tan_ch-1_p-11_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"讀書人有了歷經百般挫折也不退縮的真實心志，才能產生應對萬事萬物無窮變化的巧妙作用。建立功業，每一件事都要從腳踏實地的基礎做起，如果稍微貪圖名聲，就會變成虛偽的成果；談論道義修養德行，每一個念頭都要以空靈無私的境界為根基，如果稍微計較功效得失，就會墮入世俗的塵世情慾之中。","analysis":"【主題與背景】本條論述了「真心」與「妙用」、「立業」與「修德」的關係。士人的「真心」是應變的根本（體），有了不變的真心，才能產生萬變不窮的「妙用」（用）。\\\\n【詞義與名物】在實踐層面，立業建功必須「腳踏實地」，反對沽名釣譽，因為虛名會導致「偽果」；而講道修德則必須「從虛處立基」，即心靈要空靈、無私、無所求，如果帶著功利心去修德，就會落入世俗名利的「塵情」。\\\\n【思想與篇章】此段深刻揭示了世俗事業與靈性修養在方法論上的虛實相輔。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-12","chapterId":"cai-gen-tan_ch-1","order":12,"canonicalText":"身不宜忙，而忙於閒暇之時，亦可儆惕惰氣；心不可放，而放於收攝之後，亦可鼓暢天機。","sentenceIds":["cai-gen-tan_ch-1_p-12_s-1","cai-gen-tan_ch-1_p-12_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"身體不應當過度忙碌奔波，但如果在閒暇時適當地讓自己忙碌起來，也可以用來警惕和防範懶惰的習氣；心思不可隨意放任流蕩，但在高度專注與收斂心神之後，適當地放鬆一下，也可以振作並舒暢自然的生機。","analysis":"【主題與背景】本條講述身體的「忙與閒」以及心靈的「收與放」之調適智慧。過度忙碌會勞累身體，但過度安逸則會滋生惰性，故在閒暇時找事情做可以「儆惕惰氣」。\\\\n【詞義與名物】同樣，心神雖然需要「收攝」（集中、專注），但如果繃得太緊，心靈就會枯燥死板，因此在收攝之後適度「放」（放鬆、寬舒），反而能激發和鼓暢「天機」（天賦的靈性與自然生機）。\\\\n【思想與篇章】這是一種科學的心理調適法，符合張弛有度的中庸哲學。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-13","chapterId":"cai-gen-tan_ch-1","order":13,"canonicalText":"鐘鼓體虛，為聲聞而招擊撞；麋鹿性逸，因豢養而受羈糜。可見名為招禍之本，欲乃散志之媒。學者不可不力為掃除也。","sentenceIds":["cai-gen-tan_ch-1_p-13_s-1","cai-gen-tan_ch-1_p-13_s-2","cai-gen-tan_ch-1_p-13_s-3","cai-gen-tan_ch-1_p-13_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"鐘和鼓的內部是空虛的，卻因為要發出聲音傳播於外而招來了敲打撞擊；麋鹿的本性是安逸自由的，卻因為被人豢養而遭受了籠頭韁繩的束縛。由此可見，名聲是招致禍患的根源，慾望是消磨分散志向的媒介。學習修身的人不可以不盡力將它們清除乾淨。","analysis":"【主題與背景】本條以自然物為喻，警示名利的危害，具有濃厚的道家莊子色彩。鐘鼓因為空虛能發聲（喻人好出風頭、追求聲名），所以招致敲打；麋鹿因為貪圖人類的食物豢養（喻人貪圖物慾享受），所以失去了自由，受制於羈絆。\\\\n【詞義與名物】這生動地證明瞭老子所說的「五色令人目盲，五音令人耳聾」以及莊子關於「無用之用」的智慧。\\\\n【思想與篇章】名是招禍之本，欲是散志之媒，唯有淡泊名利、清心寡慾，才能保全天真與自由。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-14","chapterId":"cai-gen-tan_ch-1","order":14,"canonicalText":"一念常惺，纔避去神弓鬼矢；纖塵不染，方解開地網天羅。","sentenceIds":["cai-gen-tan_ch-1_p-14_s-1","cai-gen-tan_ch-1_p-14_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"心中隨時保持清醒警覺的念頭，才能躲避開神出鬼沒的明槍暗箭；內心做到不被一絲一毫的塵俗物慾所汙染，才能解脫開天羅地網般世俗羅網的束縛。","analysis":"【主題與背景】此段強調「常惺」與「不染」對於人生解脫的重要性。「一念常惺」源自禪宗與理學的修持功夫，意指心靈時刻保持清醒、覺照的狀態，不昏沉、不散亂。\\\\n【詞義與名物】如此方能覺察並避開外界那些防不勝防的「神弓鬼矢」（明槍暗箭、誘惑或災禍）。\\\\n【思想與篇章】「纖塵不染」則是佛教用語，比喻心性潔淨，不被外界的色聲香味觸法等塵境所染污，這樣才能打破世俗的名利枷鎖（地網天羅），獲得心靈的絕對自由與超脫。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-15","chapterId":"cai-gen-tan_ch-1","order":15,"canonicalText":"一點不忍的念頭，是生民生物之根芽；一段不為的氣節，是撐天撐地之柱石。故君子於一蟲一蟻不忍傷殘，一縷一絲勿容貪冒，變可為萬物立命、天地立心矣。","sentenceIds":["cai-gen-tan_ch-1_p-15_s-1","cai-gen-tan_ch-1_p-15_s-2","cai-gen-tan_ch-1_p-15_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一點點不忍心傷害他物的慈悲念頭，是繁衍人民、孕育萬物的根源萌芽；一種堅決不隨波逐流的有所不為的骨氣操守，是支撐天地世道的頂天柱石。所以君子對於一隻小昆蟲、一隻小螞蟻都不忍心去傷害殘害，對於一絲一縷的微小財物也不容許自己貪圖冒領，這樣就可以為萬物確立生生不息的生命價值，為天地樹立起道德的自覺心了。","analysis":"【主題與背景】本條是典型的儒家孟子思想的體現。「一點不忍的念頭」即是孟子所說的「惻隱之心」，是「仁」的端倪，也是「生民生物之根芽」；「一段不為的氣節」即是「羞惡之心」，是「義」的端倪，體現了有所不為的骨氣，是社會道德的「撐天撐地之柱石」。\\\\n【詞義與名物】「為萬物立命、天地立心」直接化用了宋代張載「橫渠四句」中的「為天地立心，為生民立命」，說明君子從身邊極其微小的事情做起（不傷蟲蟻、不貪絲縷），其本質就是弘揚天地人生的正道與慈悲。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-16","chapterId":"cai-gen-tan_ch-1","order":16,"canonicalText":"撥開世上塵氛，胸中自無火焰冰競；消卻心中鄙吝，眼前時有月到風來。","sentenceIds":["cai-gen-tan_ch-1_p-16_s-1","cai-gen-tan_ch-1_p-16_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"撥開世俗名利紛擾的塵俗氣氛，胸中自然不會有如烈火般燃燒的焦躁，也不會有如冰雪般寒冷的權勢爭鬥；消除掉內心深處的狹隘與鄙陋吝嗇，眼前就會時常呈現出明月高照、清風徐來的澄明開闊景象。","analysis":"【主題與背景】本條描繪了超脫物慾後的心靈美學境界。「火焰冰競」生動地比喻了世俗名利場中的雙重痛苦：一是物慾熾熱如「火焰」般的焦慮煎熬，二是人情冷暖、權勢爭奪如「冰競」（如履薄冰、如冰雪般寒冷險惡的競爭）的恐懼。\\\\n【詞義與名物】若能「撥開塵氛」，心靈便能獲得清涼。\\\\n【思想與篇章】而「鄙吝」是自我局限的根源，一旦消除了自私吝嗇，心胸開闊，便能與大自然相通，隨時感受到「月到風來」（語出宋代邵雍詩「月到天心處，風來水面時」）的那份安詳、自在與喜悅。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-17","chapterId":"cai-gen-tan_ch-1","order":17,"canonicalText":"學者動靜殊操、喧寂異趣，還是鍛煉未熟，心神混淆故耳。須是操存涵養，定雲止水中，有鳶飛魚躍的景象；風狂雨驟處，有波恬浪靜的風光，纔見處一化齊之妙。","sentenceIds":["cai-gen-tan_ch-1_p-17_s-1","cai-gen-tan_ch-1_p-17_s-2","cai-gen-tan_ch-1_p-17_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"學習修身的人如果把行動與靜止當作不同的操守，把喧鬧與寂靜看作不同的志趣，這還是因為修養鍛鍊不夠成熟，心神容易被外境混亂幹擾的緣故。必須在平時加強心性的操守與涵養，做到在如同凝定雲朵、靜止流水般的寧靜中，依然保有像鷹飛魚躍那樣生機勃勃的景象；而在風狂雨驟般險惡混亂的環境中，內心依然保有波平浪靜的安祥風光，這才能體現出物我合一、將萬物齊同看待的奧妙。","analysis":"【主題與背景】本條討論的是動靜合一的高超境界。「動靜殊操、喧寂異趣」說明修行者還停留在對立的二元思維中，被外境所牽轉。\\\\n【詞義與名物】「定雲止水中有鳶飛魚躍」是「靜中有動」，在極度安詳中葆有活潑潑的生命力；「風狂雨驟處有波恬浪靜」是「動中有靜」，在外界劇烈動盪時內心依然澄澈安寧。\\\\n【思想與篇章】「處一化齊」融合了莊子的《齊物論》與儒家的「中和」思想，表明真正的修養是不受外界客觀條件限制的，達到了動靜一體、無往而不自在的最高境地。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-18","chapterId":"cai-gen-tan_ch-1","order":18,"canonicalText":"心是一顆明珠。以物慾障蔽之，猶明珠而混以泥沙，其洗滌猶易；以情識襯貼之，猶明珠而飾以銀黃，其洗滌最難。故學者不患垢病，而患潔病之難治；不畏事障，而畏理障之難除。","sentenceIds":["cai-gen-tan_ch-1_p-18_s-1","cai-gen-tan_ch-1_p-18_s-2","cai-gen-tan_ch-1_p-18_s-3","cai-gen-tan_ch-1_p-18_s-4","cai-gen-tan_ch-1_p-18_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"譯文：此處記載心是一顆明珠。以物慾障蔽……之文意精義，詳細說明歷史風雲演變與賢哲理政哲理。","analysis":"【主題與背景】此段精闢論述了佛學中的「事障」與「理障」之別，並以明珠作喻。「物慾」如泥沙，粗俗顯眼，人容易警覺並清洗，這對應於普通的「垢病」與「事障」。\\\\n【詞義與名物】而「情識」（主觀知見、清高自許）如「銀黃」（金銀），外表美麗高貴，人往往引以為傲而不願捨棄，這對應於「潔病」與「理障」。\\\\n【思想與篇章】這與禪宗強調「破除法執」是一致的。自命清高、執著於教條和道理（理障），比單純的物慾糾纏（事障）更具隱蔽性，也更難以根除，這是修行者極易陷入的誤區。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-19","chapterId":"cai-gen-tan_ch-1","order":19,"canonicalText":"軀殼的我要看得破，則萬有皆空而其心常虛，虛則義理來居；性命的我要認得真，則萬理皆備而其心常實，實則物慾不入。","sentenceIds":["cai-gen-tan_ch-1_p-19_s-1","cai-gen-tan_ch-1_p-19_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"譯文：此處記載軀殼的我要看得破，則萬有……之文意精義，詳細說明歷史風雲演變與賢哲理政哲理。","analysis":"【主題與背景】本條探討了「小我（軀殼的我）」與「大我（性命的我）」的虛實辯證，融合了佛教的「真空」與儒家的「妙有」（或實理）。「軀殼的我」指受限於感官與物慾的肉體自我，將其看破，便能「萬有皆空」，使心常「虛」，這與莊子「唯道集虛」及儒家的「謙虛受道」相通；「性命的我」指人天生所稟受的本然之性（真我），將其認真體悟，便能發覺「萬物皆備於我」，使心常「實」，這與孟子的「充實之謂美」相合。\\\\n【詞義與名物】虛其心以容納義理，實其心以杜絕物慾，是內聖外王的重要功夫。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-20","chapterId":"cai-gen-tan_ch-1","order":20,"canonicalText":"面上掃開十層甲，眉目纔無可憎；胸中滌去數鬥塵，語言方覺有味。","sentenceIds":["cai-gen-tan_ch-1_p-20_s-1","cai-gen-tan_ch-1_p-20_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"臉上必須颳去厚達十層的虛偽裝甲，面容和神態才不會令人感到厭惡；心中必須洗去多達數斗的世俗塵垢，說出來的話語才能讓人覺得有深意與韻味。","analysis":"【訓詁與名物】「面」指臉孔；「甲」本指鎧甲，此處比喻虛偽的防備與面具。「可憎」指令人討厭、反感。「滌」指洗滌、清除。「數鬥塵」以具體的容量單位「鬥」來誇飾內心積存的世俗雜念與功利之心。「有味」指言語富有內涵、雋永而不庸俗。\\\\n【章法與結構】此段為極其工整的對仗句。「面上」對「胸中」，「掃開」對「滌去」，「十層甲」對「數鬥塵」，「眉目纔無可憎」對「語言方覺有味」。以外表的造作與內在的塵俗相對應，語意遞進，結構嚴謹。\\\\n【思想與義理】本段批判世人往往帶著虛偽的面具與滿腹的世俗功利生活。作者指出，唯有卸下外在的防備與虛飾，展現真實的自我，才能讓人感到親切；唯有清除內心的物慾與俗念，涵養純淨的心靈，言談舉止才能散發出真正的智慧與魅力。這是內外雙修的真誠之道。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-21","chapterId":"cai-gen-tan_ch-1","order":21,"canonicalText":"完得心上之本來，方可言了心；盡得世間之常道，纔堪論出世。","sentenceIds":["cai-gen-tan_ch-1_p-21_s-1","cai-gen-tan_ch-1_p-21_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"唯有保全並圓滿了自己內心原有的純真本性，才可以談得上了悟心性；唯有盡到了人世間做人處世的倫常道理，纔有資格談論超脫塵俗的出世修行。","analysis":"【主題與背景】此段指出了「入世」與「出世」的有機統一，是《菜根譚》融通儒道釋三家思想的代表性觀點。佛教講「了心」（了悟自性），但若不先「完得心上之本來」（保護天真、洗淨污染），便只是空談；道家與佛教講「出世」（超越世俗），但若連「世間之常道」（如儒家倡導的孝悌忠信、社會責任）都未能盡到，其出世往往淪為逃避責任的藉口。\\\\n【詞義與名物】這強調修行必須立足於現實人生，在人倫日用中磨練，完滿了入世的責任，才能達到真正的出世高度。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-22","chapterId":"cai-gen-tan_ch-1","order":22,"canonicalText":"我果為洪爐大冶，何患頑金鈍鐵之不可陶熔。我果為巨海長江，何患橫流污瀆之不能容納。","sentenceIds":["cai-gen-tan_ch-1_p-22_s-1","cai-gen-tan_ch-1_p-22_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"我自己如果真的是一個能熔化一切的巨大熔爐，又何必擔心那些堅硬粗糙的頑金鈍鐵不能被陶冶熔化呢？我自己如果真的是像長江巨海那樣寬廣，又何必擔心那些肆意橫流的髒水溝渠不能被容納吸收呢？","analysis":"【主題與背景】本條比喻君子應當具備的宏大格局與同化力量，具有孟子「善養吾浩然之氣」的宏偉氣魄。作者以「洪爐大冶」和「巨海長江」為喻，說明面對外界的頑劣之人（頑金鈍鐵）或惡劣環境（橫流污瀆），修行者不應一味逃避或抱怨，而應反求諸己，提升自己的心胸與感化能力。\\\\n【詞義與名物】只要自身的德行足夠深厚，格局足夠寬廣，就具備熔煉萬物、包容萬有的力量，展現了「大度能容」與「隨緣化眾」的博大襟懷。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-23","chapterId":"cai-gen-tan_ch-1","order":23,"canonicalText":"白日欺人，難逃清夜之鬼報；紅顏失志，空貽皓首之悲傷。","sentenceIds":["cai-gen-tan_ch-1_p-23_s-1","cai-gen-tan_ch-1_p-23_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在光天化日之下欺騙他人，也難以逃脫在寂靜清冷之夜內心良知的譴責與報應；在年輕時喪失了奮發向上的志向，只會給白髮蒼蒼的暮年留下無益的悲傷。","analysis":"【主題與背景】此段警示了「欺人自欺」的惡果與「少壯不努力」的悲哀。「白日欺人，難逃清夜之鬼報」，此處的「鬼報」並非單指迷信的鬼神報應，更側重指「清夜捫心」時良心的審判與不安。\\\\n【詞義與名物】在喧囂的白天人可以用面具掩人耳目，但在夜深人靜之時，靈魂深處的愧疚與恐懼會如期而至，這體現了儒家的慎獨思想。\\\\n【思想與篇章】「紅顏失志，空貽皓首之悲傷」則化用了《樂府詩集·長歌行》中的「少壯不努力，老大徒傷悲」，勉勵人們珍惜青春，立定志向，免得晚年徒增悔恨。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-24","chapterId":"cai-gen-tan_ch-1","order":24,"canonicalText":"以積貨財之心積學問，以求功名之念求道德，以愛妻子之心愛父母，以保爵位之策保國家，出此入彼，念慮只差毫末，而超凡入聖，人品且判星淵矣。人胡不猛然轉念哉！","sentenceIds":["cai-gen-tan_ch-1_p-24_s-1","cai-gen-tan_ch-1_p-24_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果能用累積金錢財富的心勁去累積學問，用追求功名利祿的念頭去追求道德修養，用疼愛妻子兒女的心意去孝敬父母，用保護自己官職爵位的策略去保衛國家；這只是將同樣的熱情與心思從追求物質名利轉化為追求精神道義，念頭的偏差僅在毫釐之間，然而所達到的境界卻是超凡入聖的差別，人品高下更是如同天上的星星與深淵般的差距。人們為什麼不猛然警醒、轉變觀念呢？","analysis":"【主題與背景】本條論述了「轉念」的巨大力量，體現了儒家與佛家的心性轉化學。作者指出，人之所以不能超凡入聖，非不能也，是不為也。\\\\n【詞義與名物】世人追求「財、名、愛、權」的能量是巨大的，只要將這股熱情與智謀「轉向」到「學問、道德、父母、國家」上，就能完成人格的昇華。\\\\n【思想與篇章】「念慮只差毫末」（念頭的方向只差一點點），而「超凡入聖，人品判若星淵」（結果卻天差地別）。這體現了「一心具足萬法，唯在轉念之間」的哲理，勉勵世人猛然回頭，將私欲轉化為大愛與大義。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-25","chapterId":"cai-gen-tan_ch-1","order":25,"canonicalText":"立百福之基，只在一念慈祥；開萬善之門，無如寸心挹損。","sentenceIds":["cai-gen-tan_ch-1_p-25_s-1","cai-gen-tan_ch-1_p-25_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"奠定一生幸福的根基，僅僅在於心中保持一個慈愛祥和的念頭；開啟實踐萬種善行的大門，沒有什麼比內心保持謙遜與自我剋制更有效的了。","analysis":"【主題與背景】本條點出幸福與行善的源頭在於「慈祥」與「挹損」。「一念慈祥」是慈悲、仁愛的體現，是儒家「仁者壽」與佛家「慈悲引福」的呼應。\\\\n【詞義與名物】慈祥之人，心平氣和，自然能感召祥和之氣，這就是「百福之基」。\\\\n【思想與篇章】「挹損」即謙遜、退讓、克己。《易經》有「謙」卦，卦辭曰「謙尊而光，卑而不可逾，君子之終也」。通過剋制私欲、虛心待人，方能容納萬物，走入行善的康莊大道。這強調了內心態度的微小轉變對命運和道德的深遠影響。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-26","chapterId":"cai-gen-tan_ch-1","order":26,"canonicalText":"塞得物慾之路，才堪闢道義之門；馳得塵俗之肩，方可挑聖賢之擔。","sentenceIds":["cai-gen-tan_ch-1_p-26_s-1","cai-gen-tan_ch-1_p-26_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"只有堵塞住追求物質慾望的道路，才能開闢出通往道義的大門；只有卸下對塵俗名利的爭奪與依戀，才能挑起傳承聖賢學問與擔當社會責任的重擔。","analysis":"【主題與背景】此段論述了道義與物慾、聖賢擔當與塵俗牽絆的此消彼長關係。「塞得物慾之路，才堪闢道義之門」，這與孟子的「養心莫善於寡慾」相通，人的精力與心思是有限的，若沉溺於感官享樂，便無暇顧及精神追求。\\\\n【詞義與名物】「弛得塵俗之肩」，即是把肩膀從世俗的名利枷鎖中解脫出來，如此纔能有寬餘的肩膀去挑起「聖賢之擔」（即張載所謂的「為往聖繼絕學，為萬世開太平」）。\\\\n【思想與篇章】這要求修行者有捨纔有得，勇於承擔大義。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-27","chapterId":"cai-gen-tan_ch-1","order":27,"canonicalText":"容得性情上偏私，便是一大學問；消得家庭內嫌雪，纔為火內栽蓮。","sentenceIds":["cai-gen-tan_ch-1_p-27_s-1","cai-gen-tan_ch-1_p-27_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"能夠包容並引導他人性格脾氣上的偏激與私心，這就是一門極大的學問；能夠消除家庭內部的嫌隙與冷漠怨恨，這才稱得上是在烈火中栽植蓮花的非凡功夫。","analysis":"【主題與背景】本條將修身學問落實於具體的社會與家庭生活中。「容得性情上偏私」體現了寬容與因材施教的智慧，對他人的缺點不苛責，而是包容並引化，這是極高的道德學問。\\\\n【詞義與名物】而家庭是人際關係中最緊密也最容易產生摩擦的地方，「嫌雪」比喻家庭成員間的隔閡與冷漠。\\\\n【思想與篇章】在紛擾、矛盾叢生的家庭中消弭恩怨，化怨氣為和諧，就如同在烈火中栽植蓮花（「火內栽蓮」是佛教禪宗術語，比喻在極度艱難險惡的環境中成就難能可貴的功德），是極具挑戰性且最切實的修行。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-28","chapterId":"cai-gen-tan_ch-1","order":28,"canonicalText":"事理因人言而悟者，有悟還有迷，總不如自悟之了了；意興從外境而得者，有得還有失，總不如自得之休休。","sentenceIds":["cai-gen-tan_ch-1_p-28_s-1","cai-gen-tan_ch-1_p-28_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"事情的道理如果因為別人的點撥而領悟，那麼領悟之後還可能重新陷入迷惑，終究比不上自己親自體悟得清清楚楚；心靈的意趣如果依賴外在環境的激發而獲得，那麼獲得之後還可能隨著環境改變而失去，終究比不上內心自我生發的悠閒與自得。","analysis":"【主題與背景】本條強調了「自省自悟」與「心性自足」的重要性，具有濃厚的禪宗「自證自悟」與孟子「求則得之，舍則失之」的色彩。依賴他人言語得到的「悟」，只是二手的知識，未融入自己的生命，因此隨後還會「迷」。\\\\n【詞義與名物】唯有通過實踐與反省得到的「自悟」，才能「了了」（完全明白）。\\\\n【思想與篇章】同樣，依賴外在的美景、娛樂激發的「意興」，隨時會因客觀條件消失而「失」，而源自內心澄明寧靜的「自得」，則是無窮無盡的「休休」（安閒、喜樂貌）。這啟示我們，精神的終極歸宿在於內求而非外索。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-29","chapterId":"cai-gen-tan_ch-1","order":29,"canonicalText":"情之同處即為性，舍情則性不可見，欲之公處即為理，舍欲則理不可明。故君子不能滅情，惟事平情而已；不能絕欲，惟期寡慾而已。","sentenceIds":["cai-gen-tan_ch-1_p-29_s-1","cai-gen-tan_ch-1_p-29_s-2","cai-gen-tan_ch-1_p-29_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"情感中共同的本質就是本性，如果捨棄了情感，那麼天賦本性也就無法顯現；慾望中合乎大眾公理的部分就是天理，如果排斥了所有慾望，那麼天理也就無從闡明。所以，君子並不要求完全消滅情感，只是追求將情感調節到平和公正的狀態；君子並不要求完全斷絕慾望，只是期盼能減少私慾罷了。","analysis":"【主題與背景】本條展現了極其開明且務實的儒家「性情論」與理學反思，反對宋代理學極端化時「存天理，滅人慾」的教條。作者指出，「情」與「性」、「欲」與「理」並非絕對對立，而是體與用的關係。\\\\n【詞義與名物】「情之同處」（人類共通的良善情感）即是本性；「欲之公處」（大眾合理的生存發展需求）即是天理。\\\\n【思想與篇章】如果一味地「滅情絕欲」，就會走向虛無與僵死。因此，君子的修行是「平情」（使情感中節，如《中庸》之「發而皆中節謂之和」）與「寡慾」（減少過度的私欲，如孟子「養心莫善於寡慾」），而非滅絕人性，這極具人本主義光輝。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-30","chapterId":"cai-gen-tan_ch-1","order":30,"canonicalText":"欲遇變而無倉忙，須向常時念念守得定；欲臨死而無貪戀，須向生時事事看得輕。","sentenceIds":["cai-gen-tan_ch-1_p-30_s-1","cai-gen-tan_ch-1_p-30_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"想要在遇到突發變故時不驚慌失措，必須在平時生活裡起心動念處都能堅守定力；想要在臨終之際心中沒有任何牽掛與貪戀，必須在活著的時候將世間的萬事萬物都看得很淡然。","analysis":"【主題與背景】本條講述了「遇變」與「臨終」的修養工夫，融會了儒家的「持志」與佛家的「生死觀」。突發變故（遇變）考驗的是平時的定力，若日常不能「念念守得定」，事到臨頭必然手忙腳亂。\\\\n【詞義與名物】臨終（臨死）則是人生最大的考驗，若活著時對名利、親情、肉體過度執著，死時必然痛苦萬分、充滿貪戀。\\\\n【思想與篇章】唯有在「生時事事看得輕」，體悟世事無常，才能在生命終結時坦然面對，無牽無掛。這是一種超越生死的智慧，體現了「向死而生」的修為。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-31","chapterId":"cai-gen-tan_ch-1","order":31,"canonicalText":"一念過差，足喪生平之善；終身檢飭，難蓋一事之愆。","sentenceIds":["cai-gen-tan_ch-1_p-31_s-1","cai-gen-tan_ch-1_p-31_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一個念頭的嚴重偏差和錯誤，就足以毀掉平生積累的所有善行；即便終身都在謹慎檢點約束自己，也很難掩蓋或抹去某一件重大過失所造成的汙點。","analysis":"【主題與背景】本條是關於修身持守的嚴厲警示，強調防微杜漸與晚節的重要性。「一念過差，足喪生平之善」，這與「一失足成千古恨」相通，在關鍵時刻的一念之差、行差踏錯，可能導致道德防線的全面崩潰，毀掉一生的清譽。\\\\n【詞義與名物】「終身檢飭，難蓋一事之愆」，說明污點一旦形成，其負面影響是極難消除的。\\\\n【思想與篇章】這並非否定悔過自新的可能，而是以極其嚴肅的態度告誡修行者，在品德修養上必須如履薄冰，時刻保持高度的警惕性，不可有絲毫放任與僥倖心理。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-32","chapterId":"cai-gen-tan_ch-1","order":32,"canonicalText":"從五更枕蓆上參勘心體，氣未動，情未萌，纔見本來面目；向三時飲食中諳練世味，濃不欣，淡不厭，方為切實工夫。","sentenceIds":["cai-gen-tan_ch-1_p-32_s-1","cai-gen-tan_ch-1_p-32_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在清晨五更將醒未醒的枕蓆之間去參悟體會心靈的本體，這時外界的氣息尚未浮動，內心的情慾尚未萌發，最能看清自己本來的純真面目；在每日三餐的飲食之中去熟悉體驗世間的滋味，味道濃厚時不狂喜貪戀，味道清淡時也不心生厭惡，這才是切切實實的修行功夫。","analysis":"【主題與背景】本條將高深的「參勘心體」與日常的「一日三餐」相結合，體現了禪宗「平常心是道」與儒家「即庶民以顯真體」的精神。「五更枕蓆上」是人心最安靜、最接近先天本然狀態的時刻（氣未動，情未萌），在此時最易體悟到佛教所謂的「父母未生前本來面目」或儒家的「良知」。\\\\n【詞義與名物】「三時飲食中」則是具體的日常磨練，面對佳餚不生貪愛（濃不欣），面對粗茶淡飯不生怨懌（淡不厭），在平淡的生活瑣事中保持平等心與平常心，這才是真正落地、切實的修行功夫。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-33","chapterId":"cai-gen-tan_ch-1","order":33,"canonicalText":"操存要有真宰，無真宰則遇事便倒，何以植頂天立地之砥柱！應用要有圓機，無圓機則觸物有礙，何以成旋乾轉坤之經綸！","sentenceIds":["cai-gen-tan_ch-1_p-33_s-1","cai-gen-tan_ch-1_p-33_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在操守與心境的保持上，必須要有一個真實的主宰；如果沒有這個主宰，遇到事情就會輕易動搖倒下，這樣如何能立起頂天立地、中流砥柱般的棟樑呢？在應事接物的具體應用上，必須具備圓融變通的機智；如果沒有這種圓通的智慧，接觸世俗人事物就會處處碰壁產生阻礙，這樣又如何能成就扭轉乾坤、治理天下的宏圖大業呢？","analysis":"【主題與背景】本篇強調「定心」與「圓通」在涉世與修身中的辯證統一關係。「真宰」源自《莊子·齊物論》，此處指內心堅定不移的操守、道德主體與主宰力。\\\\n【詞義與名物】沒有真宰，人就容易在外界誘惑或困境中迷失、倒下，無法發揮中流砥柱的作用。\\\\n【思想與篇章】「圓機」則指隨機應變、圓融無礙的處事智慧。儒家講「立本」，道家講「圓通」，本條將二者結合，說明立身需有剛正不阿的道德底線，處事需有靈活通達的智慧，方能既保全人格，又能成就經邦濟世的偉業。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-34","chapterId":"cai-gen-tan_ch-1","order":34,"canonicalText":"士君子之涉世，於人不可輕為喜怒，喜怒輕，則心腹肝膽皆為人所窺；於物不可重為愛憎，愛憎重，則意氣精神悉為物所制。","sentenceIds":["cai-gen-tan_ch-1_p-34_s-1","cai-gen-tan_ch-1_p-34_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"讀書人和君子在社會上為人處事，對於他人不應該輕易表現出喜歡或憤怒的情緒，如果喜怒的情緒太輕易表露，那麼內心的真實想法與底細就會全部被別人看穿；對於事物不應該過度產生偏愛或厭惡，如果愛憎的執念太重，那麼自己的意志與精神就會完全被外物所控制與奴役。","analysis":"【訓詁與名物】「士君子」指有學問、有道德修養的人。「涉世」意為經歷世事、參與社會。「輕為喜怒」指輕易表露喜悅與憤怒的情緒。「心腹肝膽」比喻內心深處的真實想法與隱密。「窺」指暗中察看、看破。「重為愛憎」指過度強烈的喜好與厭惡。「意氣精神」指人的心志與精力。「制」指控制、牽絆。\\\\n【章法與結構】全段以「於人...，...；於物...，...」的駢偶句式構成。前半段談待人，強調情緒不可輕露；後半段談對物，強調欲望不可過重。兩相對照，條理清晰地論述了涉世的兩大原則。\\\\n【思想與義理】此段蘊含著深厚的處世哲學。在人際交往中，情緒的隨意發洩不僅顯得輕浮，更易將自己的弱點暴露無遺，從而失去主動權；在面對物質世界時，過度的貪求或抗拒，都會使心靈失去自由，淪為外物的奴隸。作者主張「喜怒不形於色」與「不物於物」，以保持心靈的平靜與獨立。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-35","chapterId":"cai-gen-tan_ch-1","order":35,"canonicalText":"倚高才而玩世，背後須防射影之蟲；飾厚貌以欺人，面前恐有照膽之鏡。","sentenceIds":["cai-gen-tan_ch-1_p-35_s-1","cai-gen-tan_ch-1_p-35_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仗恃著自己才華超羣而玩世不恭的人，必須防範背後有含沙射影的小人暗中陷害；偽裝出忠厚老實的外貌來欺騙他人的人，要提防面前恐怕有能看穿人心、照亮肝膽的明鏡揭穿偽裝。","analysis":"【主題與背景】此處警示世人不可恃才傲物，亦不可虛偽欺人。「倚高才而玩世」易招致嫉恨，給心術不正者（「射影之蟲」，典出「含沙射影」的傳說）留下可乘之機；「飾厚貌以欺人」則終究會被時間或智者（「照膽之鏡」，典出《西京雜記》中秦咸陽宮能照人五臟的照膽鏡）看穿。\\\\n【詞義與名物】這段話勸戒人們要謙虛內斂、真誠待人，切忌以小聰明玩弄世途。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-36","chapterId":"cai-gen-tan_ch-1","order":36,"canonicalText":"心體澄徹，常在明鏡止水之中，則天下自無可厭之事；意氣和平，賞在麗日光風之內，則天下自無可惡之人。當是非邪正之交，不可少遷就，少遷就則失從違之正；值利害得失之會，不可太分明，太分明則起趨避之私。","sentenceIds":["cai-gen-tan_ch-1_p-36_s-1","cai-gen-tan_ch-1_p-36_s-2","cai-gen-tan_ch-1_p-36_s-3","cai-gen-tan_ch-1_p-36_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"心靈的本體如果澄澈明亮，經常保持在明鏡止水般的寧靜狀態，那麼天下自然就沒有什麼令人厭煩的事；性情如果平和溫煦，經常如同處在明麗陽光與和風之中，那麼天下自然就沒有什麼可惡的人。當面臨是非黑白、邪正交錯的關鍵關頭，絕不能有絲毫妥協遷就，稍微遷就就會失去取捨判斷的正道；當面對利害得失的糾葛時，則不必計較得太過清清楚楚，如果過於斤斤計較，就會萌生趨利避害的自私之心。","analysis":"【主題與背景】本篇分為前後兩部分，前半部分探討心境對外界感知的決定作用，主張以「明鏡止水」和「光風霽月」的和諧心境包容世界，如此便能消解主觀的厭惡與偏見。後半部分則指出處世的兩大原則：在涉及道德、正義等「是非邪正」的大是大非原則問題上，必須堅持底線，絕不妥協；而在面對物質利益、個人得失等「利害得失」的私利問題上，則宜糊塗寬容，不可斤斤計較，以免陷入自私自利的泥潭。\\\\n【詞義與名物】這展現了儒家義利之辨與佛道圓融智慧的結合。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-37","chapterId":"cai-gen-tan_ch-1","order":37,"canonicalText":"蒼蠅附驥，捷則捷矣，難辭處後之羞；蘿蔦依松，高則高矣，未免仰攀之恥。所以君子寧以風霜自挾，毋為魚鳥親人。","sentenceIds":["cai-gen-tan_ch-1_p-37_s-1","cai-gen-tan_ch-1_p-37_s-2","cai-gen-tan_ch-1_p-37_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"蒼蠅附著在千里馬的尾巴上，跑得雖然快，卻難免尾隨於後的羞愧；女蘿與蔦草依附在青松上，爬得雖然高，卻免不了仰賴攀附的恥辱。所以君子寧可抱持著如風霜般的孤傲氣節自我持守，也絕不為了野心利益像魚鳥般去親近討好他人。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈修身〉第 37 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「蒼蠅附驥捷則捷矣難辭處後之羞蘿蔦依松高則……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「蒼」、「蠅」、「附」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-1_p-37）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-38","chapterId":"cai-gen-tan_ch-1","order":38,"canonicalText":"好醜心太明，則物不契；賢愚心太明，則人不親。士君子須是內精明而外渾厚，使好醜兩得其平，賢愚共受其益，纔是生成的德量。","sentenceIds":["cai-gen-tan_ch-1_p-38_s-1","cai-gen-tan_ch-1_p-38_s-2","cai-gen-tan_ch-1_p-38_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如果對事物美醜的計較心太過分明，就無法與萬物相契合；如果對人賢能或愚笨的成見太過強烈，別人就不敢前來親近。君子必須做到內在精明透徹而外表寬厚渾樸，使美好與醜惡的事物都能得到公正包容的對待，讓賢能與愚笨的人都能共同受到益處，這才是天性涵養而成的寬宏器量。","analysis":"【主題與背景】本條主張「和光同塵」的處事智慧。過於偏激的美醜、賢愚之分，會導致人與物、人與人之間的隔閡與對立。\\\\n【詞義與名物】君子應具備「內精明而外渾厚」的特質，即內心黑白分明、洞若觀火，外在表現卻能包容萬物，不以一己之好惡去苛責他人。\\\\n【思想與篇章】這種寬容的德量能化解戾氣，使不同層次、不同特質的人事物都能在君子的感化下各得其所，展現了儒家有教無類與道家包容萬物的博大胸懷。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-39","chapterId":"cai-gen-tan_ch-1","order":39,"canonicalText":"伺察以為明者，常因明而生暗，故君子以恬養智；奮迅以為速者，多因速度而致遲，故君子以重持輕。士君子濟人利物，宜居其實，不宜居其名，居其名則德損；士大夫憂國為民，當有其心，不當有其語，有其語則毀來。","sentenceIds":["cai-gen-tan_ch-1_p-39_s-1","cai-gen-tan_ch-1_p-39_s-2","cai-gen-tan_ch-1_p-39_s-3","cai-gen-tan_ch-1_p-39_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"將暗中窺伺打探當作精明的人，往往會因為這種小聰明而產生自我矇蔽，所以君子用恬靜淡泊來涵養真正的智慧；將急躁狂奔當作快速的人，往往會因為過分追求速度反而導致延誤 and 遲緩，所以君子用沉穩莊重來駕馭輕率浮躁。君子接濟他人、利益萬物，應當注重實際的付出，而不應當貪圖慈善的名聲，一味追求名聲反而會使德行受損；士大夫憂國憂民，應當在內心懷有這份真誠，而不應當掛在嘴邊炫耀，一旦口惠而實不至，或者四處標榜，毀謗就會隨之而來。","analysis":"【主題與背景】本篇探討「大智若愚」與「實至名歸」的修行與處世之道。前段指出「伺察」與「奮迅」看似聰明與迅速，實則是急功近利的小聰明，往往導致「因明生暗」與「速而致遲」的後果。\\\\n【詞義與名物】因此，君子主張「以恬養智」、「以重持輕」，保持內心的寧靜與沉穩。\\\\n【思想與篇章】後段進一步指出，行善利物應求實效而非虛名，憂國憂民重在實踐而非空談口號。若徒有虛名口號，不僅損害真實德行，更容易招致外界的猜忌與毀謗。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-40","chapterId":"cai-gen-tan_ch-1","order":40,"canonicalText":"遇大事矜持者，小事必縱弛；處明庭檢飾者，暗室必放逸。君子只是一個念頭持到底，自然臨小事如臨大敵，坐密室若坐通衢。","sentenceIds":["cai-gen-tan_ch-1_p-40_s-1","cai-gen-tan_ch-1_p-40_s-2","cai-gen-tan_ch-1_p-40_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"遇到大事才刻意拘謹剋制的人，在日常小事上必然放縱懈怠；身處公開明亮的場合才檢點修飾的人，在無人看見的暗室中必然放縱逸樂。君子則是將一個真誠的善念堅持到底，因此自然能在面對小事時如同面臨大敵般謹慎，獨自坐在密室中也如同坐在人來人往的繁華大道上一般嚴以律己。","analysis":"【主題與背景】本條深入闡述儒家「慎獨」的工夫。如果一個人的道德操守只在「大事」或「明庭」（公開場合）上裝點門面，說明其修行是虛偽且不穩固的，一旦到了「小事」或「暗室」（私密空間），其真面目就會暴露。\\\\n【詞義與名物】君子則講求「一念持到底」，內外一致、始終如一。\\\\n【思想與篇章】無論是在微不足道的小事上，還是在無人監督的隱祕處，都能保持高度的自律與敬畏心（「臨小事如臨大敵，坐密室若坐通衢」），這才是真正純粹的修養。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-41","chapterId":"cai-gen-tan_ch-1","order":41,"canonicalText":"使人有面前之譽，不若使其無背後之毀；使人有乍交之歡，不若使其無久處之厭。","sentenceIds":["cai-gen-tan_ch-1_p-41_s-1","cai-gen-tan_ch-1_p-41_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"讓人在你面前對你大加讚譽，不如讓人在你背後不對你產生毀謗；讓人在剛結交時感到十分歡喜，不如讓人在長期相處後不對你產生厭惡。","analysis":"【訓詁與名物】「譽」指稱讚、誇獎。「毀」指毀謗、詆毀。「乍交之歡」指剛開始交往時的歡樂與熱情，乍為初、剛開始之意。「久處之厭」指經過長時間相處後所產生的厭煩與反感。\\\\n【章法與結構】這是一組非常標準的對偶句。「使人有面前之譽」對「使人有乍交之歡」，「不若使其無背後之毀」對「不若使其無久處之厭」。採用「與其...不若...」的句型，將短暫表面的美好與長久真實的品德進行對比，語氣平和而意蘊深遠。\\\\n【思想與義理】這段話揭示了人際關係中「真實」與「長久」的價值。當面的讚美往往帶有虛偽與奉承，而背後沒有批評，才是真正無愧於心的品德體現；初見的熱情容易營造，但長期相處而不令人厭煩，則需要真實的修養與寬容。這提醒人們不要追求表面的榮耀與一時的熱烈，而應致力於培養經得起時間考驗的德性與人際關係。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-42","chapterId":"cai-gen-tan_ch-1","order":42,"canonicalText":"善啟迪人心者，當因其所明而漸通之，毋強開其所閉；善移風化者，當因其所易而漸及之，毋輕矯其所難。","sentenceIds":["cai-gen-tan_ch-1_p-42_s-1","cai-gen-tan_ch-1_p-42_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"善於開導啟迪他人心智的人，應當順著對方已經明白 the 道理來逐漸引導通達，不要強行去開啟對方封閉而無法接受的領域；善於改變社會風俗教化大眾的人，應當從比較容易變革的部分著手引導，逐漸推廣，不要輕易去強行矯正那些根深蒂固、極難改變的積弊。","analysis":"【主題與背景】本條探討教育與社會改革的「循序漸進」原則。啟迪人心如同疏導水源，必須因勢利導，從對方已有的認知（「所明」）出發，若強行灌輸其無法理解的知識（「所閉」），只會適得其反。\\\\n【詞義與名物】在社會治理與風俗改良上，亦應從阻力較小、容易推行的方面（「所易」）漸進推廣，若急於求成、強行糾正深層頑疾（「所難」），容易激起強烈反彈。\\\\n【思想與篇章】這體現了孟子「因勢利導」與孔子「欲速則不達」的智慧。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-43","chapterId":"cai-gen-tan_ch-1","order":43,"canonicalText":"彩筆描空，筆不落色，而空亦不受染；利刀割水，刀不損鍔，而水亦不留痕。得此意以持身涉世，感與應俱適，心與境兩忘矣。","sentenceIds":["cai-gen-tan_ch-1_p-43_s-1","cai-gen-tan_ch-1_p-43_s-2","cai-gen-tan_ch-1_p-43_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"用彩色的畫筆去描繪虛空，筆端不會掉落色彩，而虛空也不會被染上顏色；用鋒利的刀劍去切割流水，刀刃不會受損，而流水也不會留下任何刀痕。如果能體會這種境界來修養身心、經歷世事，那麼自身與外界的感應都能恰到好處，內心與外境都能同時忘卻而不受牽絆。","analysis":"【訓詁與名物】「彩筆描空」比喻徒勞無功或不留痕跡，其中「空」指虛空；「不損鍔」的「鍔」指刀劍的邊緣或鋒刃；「持身涉世」意即修養自身並與世間打交道；「感與應」指內心的感受與外在事物的反應。「兩忘」是指內外物我合一、不受拘束的境界。\\\\n【章法與結構】本段採用駢散結合的句式。前兩句「彩筆描空...而空亦不受染」與「利刀割水...而水亦不留痕」形成工整的對偶，藉由具體的物理現象作比喻。最後一句「得此意以持身涉世...」則點出主旨，從物象昇華至心境，層層遞進，收束有力。\\\\n【思想與義理】此句深受佛道思想影響，傳達出一種「空靈」與「無為」的處世哲學。筆不染空、刀不留痕，象徵人在塵世中雖有作為，但不應讓外物滯留於心，也不應讓自我的執著損害本心。唯有達到「心境兩忘」的超然態度，方能在紛繁複雜的人際與世事中游刃跳脫，隨遇而安。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-44","chapterId":"cai-gen-tan_ch-1","order":44,"canonicalText":"己之情慾不可縱，當用逆之之法以制之，其道只在一忍字；人之情慾不可拂，當用順之之法以調之，其道只在一恕字。今人皆恕以適己而忍以制人，毋乃不可乎！","sentenceIds":["cai-gen-tan_ch-1_p-44_s-1","cai-gen-tan_ch-1_p-44_s-2","cai-gen-tan_ch-1_p-44_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"自己的情慾絕對不能放縱，應當用剋制的方法去約束它，其祕訣只在一個「忍」字；別人的情慾不能輕易違背，應當用順應和體諒的方法去協調它，其祕訣只在一個「恕」字。現在的人卻往往用寬恕來迎合縱容自己，用隱忍剋制來強求他人，這難道不是大錯特錯了嗎？","analysis":"【主題與背景】本條探討自我剋制與待人寬容的修養辯證法。對己要「嚴」，故用「忍」字來剋制私欲、違逆偏私的情感；對人要「寬」，故用「恕」字（推己及人）來體諒人性的弱點，不橫加干涉。\\\\n【詞義與名物】作者敏銳地指出世人常見的通病——「寬以待己，嚴以律人」（「恕以適己而忍以制人」），並提出棒喝，提倡將儒家的「克己復禮」與「忠恕之道」正確應用於自身與人際關係中。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-45","chapterId":"cai-gen-tan_ch-1","order":45,"canonicalText":"好察非明，能察能不察之謂明；必勝非勇，能勝能不勝之謂勇。","sentenceIds":["cai-gen-tan_ch-1_p-45_s-1","cai-gen-tan_ch-1_p-45_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"喜歡明察秋毫並不算是真正的明智，能夠洞察一切卻又懂得適時裝糊塗，才稱得上是真正的明智；逢敵必求取勝並不算是真正的勇敢，有能力戰勝卻又懂得適時退讓不爭，才稱得上是真正的勇敢。","analysis":"【訓詁與名物】「好察」指喜歡追究細節、過於精明；「明」指明智、聰明。「能不察」意為懂得包容或適度忽略。「必勝」指事事都要贏過別人；「能不勝」則是不執著於勝負，懂得退一步海闊天空。\\\\n【章法與結構】全段由兩個句型完全對稱的複合句構成：「好察非明...之謂明」對應「必勝非勇...之謂勇」。先破後立，先否定世俗對「明」與「勇」的淺薄認知，隨即給出更高層次的定義，邏輯嚴密且語意精警，富有格言體的特色。\\\\n【思想與義理】作者在此闡發了儒家與道家融合的中庸及退守哲學。「能察能不察」體現了「難得糊塗」的智慧，過於精明易致苛刻，適度寬容才能和諧。「能勝能不勝」則是老子「不爭而善勝」的實踐。真正的明智與勇敢不在於處處顯露鋒芒，而在於懂得收斂與包容，這是一種更高境界的涵養。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-46","chapterId":"cai-gen-tan_ch-1","order":46,"canonicalText":"隨時之內善救時，若和風之消酷暑；混俗之中能脫俗，似淡月之映輕雲。","sentenceIds":["cai-gen-tan_ch-1_p-46_s-1","cai-gen-tan_ch-1_p-46_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在順應時代大勢的同時，要善於匡正、挽救時弊，這就如同溫和的涼風消散了炎熱的酷暑；在混跡世俗的社交中，能保持自我超凡脫俗，這就像清淡的月光映照在薄薄的輕雲之中。","analysis":"【主題與背景】本篇以極具詩意的意象，描繪了士君子「入世」與「出世」的和諧統一。「隨時」是順應時代，「救時」是承擔責任，君子救時不以暴易暴，而是像和風消暑般溫和而持久；「混俗」是融入大眾，「脫俗」是保持操守，如同淡月映輕雲，既不與世俗隔絕，又保持了高潔獨立的品格。\\\\n【詞義與名物】這種處世藝術達到了儒家濟世與道家超然的和諧境界。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-47","chapterId":"cai-gen-tan_ch-1","order":47,"canonicalText":"思入世而有為者，須先領得世外風光，否則無以脫垢濁之塵緣；思出世而無染者，須先諳盡世中滋味。否則無以持空寂之後苦趣。","sentenceIds":["cai-gen-tan_ch-1_p-47_s-1","cai-gen-tan_ch-1_p-47_s-2","cai-gen-tan_ch-1_p-47_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"想要投身世俗、建功立業的人，必須先領略世俗之外超然物外的風光，否則就無法擺脫汙濁名利的塵緣束縛；想要超脫紅塵、清修無染的人，必須先嘗盡世俗生活的各種酸甜苦辣，否則就無法持守出世後那份空虛寂寞的清苦境地。","analysis":"【主題與背景】本條深刻探討了「入世」與「出世」的互為根基關係。欲入世有為，須有出世的超然襟懷，否則極易在名利場中沉淪墮落；欲出世修行，須先體驗並看穿世俗的繁華與百態，否則只是盲目逃避，一旦面臨出世後漫長的枯寂與清苦（「空寂之苦趣」），便會心生動搖，難以堅持。\\\\n【詞義與名物】這體現了《菜根譚》融合儒道禪、主張在現實與超脫之間尋找平衡的實踐智慧。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-48","chapterId":"cai-gen-tan_ch-1","order":48,"canonicalText":"與人者，與其易疏於終，不若難親於始；御事者，與其巧持於後，不若拙守於前。","sentenceIds":["cai-gen-tan_ch-1_p-48_s-1","cai-gen-tan_ch-1_p-48_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"與人交往，與其在最後因為相處不睦而輕易疏遠，不如在開始時保持距離、不輕易親熱；處理事情，與其在後期出現紕漏時投機取巧、勉力維持，不如在開始時恪守本分、腳踏實地做好預防。","analysis":"【主題與背景】本條指出人際交往與做事的基本原則。人際交往若「易親」則往往「易散」，一開始過於熱絡往往缺乏深厚基礎，因此「難親於始」反能維持長久恆溫的關係（即君子之交淡如水）；做事若初期不謹慎，後期就要靠百般技巧（「巧持」）去彌補，往往疲於奔命且成效不彰，不如一開始就「拙守」原則、打好基礎。\\\\n【詞義與名物】這體現了「重在防微杜漸」與「真誠務實」的智慧。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-49","chapterId":"cai-gen-tan_ch-1","order":49,"canonicalText":"酷烈之禍，多起於翫忽之人；盛滿之功，常敗於細微之事。故語雲：「人人道好，須防一人著腦；事事有功，須防一事不終。」","sentenceIds":["cai-gen-tan_ch-1_p-49_s-1","cai-gen-tan_ch-1_p-49_s-2","cai-gen-tan_ch-1_p-49_s-3","cai-gen-tan_ch-1_p-49_s-4","cai-gen-tan_ch-1_p-49_s-5"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"譯文：此處記載酷烈之禍，多起於翫忽之人……之文意精義，詳細說明歷史風雲演變與賢哲理政哲理。","analysis":"【主題與背景】本條警示世人在成功與順境中要防微杜漸、持盈履滿。「酷烈之禍」源於一時的懈怠（翫忽），「盛滿之功」毀於細微的漏洞。\\\\n【詞義與名物】引用古語「人人道好，須防一人著腦；事事有功，須防一事不終」，強調了在人際關係中不可忽視任何一個潛在的對立面（哪怕只有一人怨恨也可能壞事），在行事時必須持之以恆、慎終如始，避免功虧一簣。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-50","chapterId":"cai-gen-tan_ch-1","order":50,"canonicalText":"功名富貴，直從滅處觀究竟，則貪戀自輕；橫逆困窮，直從起處究由來，則怨尤自息。","sentenceIds":["cai-gen-tan_ch-1_p-50_s-1","cai-gen-tan_ch-1_p-50_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"面對世間的功名富貴，如果直接從它終將消逝、破滅的結局來觀察其本質，貪戀之心自然就會減輕；面對生活中的坎坷橫禍與貧病困頓，如果直接從事情發生的起點去探究其因果根源，怨天尤人的情緒自然就會平息。","analysis":"【主題與背景】本條提供了一種超脫得失、坦然面對逆境的心靈調節方法。對待順境中的「功名富貴」，運用佛教的「無常」與「成住壞空」觀點，從其終將煙消雲散的結局（滅處）來看，便能破除執著；對待逆境中的「橫逆困窮」，運用儒家反求諸己與因果邏輯，從其產生的源頭（起處）去追尋原因，明白事出有因，便能消解怨恨。\\\\n【詞義與名物】這種思維方式有助於在無常的塵世中保持心態的平和與淡定。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-51","chapterId":"cai-gen-tan_ch-1","order":51,"canonicalText":"宇宙內事要力擔當，又要善擺脫。不擔當，則無經世之事業；不擺脫，則無出世之襟期。","sentenceIds":["cai-gen-tan_ch-1_p-51_s-1","cai-gen-tan_ch-1_p-51_s-2","cai-gen-tan_ch-1_p-51_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"天地間的世俗事務，既要盡力去擔當責任，又要善於擺脫名韁利鎖。如果不去擔當，就無法成就經世濟民的功業；如果不善於擺脫，就無法具備超脫俗世的廣闊胸襟。","analysis":"【主題與背景】本條深刻揭示了儒家「有為」與道家「無為」的和諧統一。「力擔當」是儒家的入世精神，強調責任、使命與社會價值的實現，沒有擔當就談不上經世濟民；「善擺脫」是老莊與禪宗的出世智慧，強調心靈的自由與不執著於功名利祿。\\\\n【詞義與名物】君子應當既能挑起千鈞重擔，又能隨時放下得失心，如此才能既有事業的成就，又有心靈的超脫。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-52","chapterId":"cai-gen-tan_ch-1","order":52,"canonicalText":"待人而留有餘，不盡之恩禮，則可以維繫無厭之人心；御事而留有餘，不盡之才智，則可以提防不測之事變。","sentenceIds":["cai-gen-tan_ch-1_p-52_s-1","cai-gen-tan_ch-1_p-52_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"對待他人要留有餘地，不一次用盡所有的恩惠與禮遇，這樣才可以維繫並引導貪得無厭的人心；處理事情要留有餘力，不一次使盡所有的才華與智謀，這樣才可以防範突如其來、無法預料的事態變化。","analysis":"【主題與背景】本條闡述處世應物中的「留有餘地」哲學。對人而言，人的欲望往往難以滿足，如果一開始就給予極致的恩禮（「盡之恩禮」），一旦後續稍有減少便會招致怨恨，唯有「留有餘」才能持續維繫人心；對事而言，若將智慧與力量用盡而不留退路，一旦遇到突發危機便無牌可打。\\\\n【詞義與名物】因此，「留有餘」是一種極高明的防禦性智慧與中庸之道。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-53","chapterId":"cai-gen-tan_ch-1","order":53,"canonicalText":"了心自了事，猶根拔而草不生；逃世不逃名，似羶存蚋而仍集。","sentenceIds":["cai-gen-tan_ch-1_p-53_s-1","cai-gen-tan_ch-1_p-53_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"了卻了內心的執著，世俗的煩惱事自然就會了結，這就如同拔去了野草的根，雜草就不會再行生長；隱居避世卻不肯放棄虛名，就如同身上殘留著腥羶之氣，蚊蠅依然會聚集過來。","analysis":"【主題與背景】本條結合禪宗的「治心」思想，指出修行與避世的關鍵在於「斷除心念之根」與「擺脫名利之絆」。「了心自了事」說明萬事皆由心造，斷除內心的執著才是根本解決之道（「根拔而草不生」）。\\\\n【詞義與名物】如果只是形式上歸隱山林（「逃世」），內心卻依然渴望塵世的名聲（「不逃名」），那隻不過是自欺欺人，如同羶肉招引蚊蠅（「羶存蚋集」）一樣，煩惱與是非依然會不請自來。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-54","chapterId":"cai-gen-tan_ch-1","order":54,"canonicalText":"仇邊之弩易避，而恩裏之戈難防；苦時之坎易逃，而樂處之阱難脫。","sentenceIds":["cai-gen-tan_ch-1_p-54_s-1","cai-gen-tan_ch-1_p-54_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"來自仇敵那方的明槍暗箭容易躲避，但隱藏在恩寵關懷之中的暗算卻極難防範；處於痛苦逆境時的坎坷容易設法逃脫，但沉溺於安樂享受時所設下的陷阱卻難以擺脫。","analysis":"【主題與背景】此處警示人們防範人生的隱形危機。人對於明目張膽的仇恨（「仇邊之弩」）和顯而易見的逆境（「苦時之坎」），往往會高度警惕，因而容易避開；然而，面對偽裝在「恩情」之中的傷害（「恩裏之戈」）以及令人沉溺的安樂溫柔鄉（「樂處之阱」），人往往會喪失戒備，最終泥足深陷、無法自拔。\\\\n【詞義與名物】這與「生於憂患，死於安樂」的古訓相通，告誡世人必須在順境與溫情中保持清醒。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-55","chapterId":"cai-gen-tan_ch-1","order":55,"canonicalText":"羶穢則蠅蚋叢嘬，芳馨則蜂蝶交侵。故君子不作垢業，亦不立芳名。只是元氣渾然，圭角不露，便是持身涉世一安樂窩也。","sentenceIds":["cai-gen-tan_ch-1_p-55_s-1","cai-gen-tan_ch-1_p-55_s-2","cai-gen-tan_ch-1_p-55_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"羶腥汙穢自然會引來蚊蠅聚集叮咬，芬芳香甜也免不了招致蜂蝶紛紛侵擾。因此，君子既不做汙濁的惡業，也不刻意去樹立高尚的名聲。只是保持天真渾樸的本氣，不顯露任何鋒芒，這便是立身涉世最安全舒適的避風港。","analysis":"【主題與背景】本條體現了道家「無名」與「藏鋒」的養生哲學。污穢之物（「垢業」）固然招來禍患，但即便是高尚的「美名」（「芳名」），也同樣會招致嫉妒、侵擾與非議，這就是「芳馨則蜂蝶交侵」的道理。\\\\n【詞義與名物】因此，最上乘的處世方式是回歸自然渾樸的狀態（「元氣渾然」），收斂鋒芒（「圭角不露」），在不偏不倚的中庸與無為中保全自我，獲得心靈的安樂。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-56","chapterId":"cai-gen-tan_ch-1","order":56,"canonicalText":"從靜中觀物動，向閒處看人忙，纔得超塵脫俗的趣味；遇忙處會偷閒，處鬧中能取靜，便是安身立命的工夫。","sentenceIds":["cai-gen-tan_ch-1_p-56_s-1","cai-gen-tan_ch-1_p-56_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"從寧靜的境界中觀察萬物的變動，在清閒的立足點觀看世人的奔波忙碌，才能體會到超凡脫俗的意趣；在忙碌的事務中懂得抽空偷閒，在喧囂的環境中能夠保持內心寧靜，這才是安身立命的真正工夫。","analysis":"【主題與背景】本條論述「心靈主宰力」在鬧靜與忙閒之中的體現。前半句是「靜中觀動」，是一種旁觀者超然的審美視角，能讓人跳出局外，獲得超塵的樂趣；後半句「忙中取靜」則是更高的實踐功夫，要求人在身處紅塵俗務的漩渦時，依然能維持內在心靈的寧靜與秩序。\\\\n【詞義與名物】這是不離世間法而得解脫的禪宗境界，是安身立命的重要心靈法則。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-57","chapterId":"cai-gen-tan_ch-1","order":57,"canonicalText":"邀千百人之歡，不如釋一人之怨；希千百事之榮，不如免一事之醜。","sentenceIds":["cai-gen-tan_ch-1_p-57_s-1","cai-gen-tan_ch-1_p-57_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"想方設法去迎合並博取成百上千人的歡心，倒不如去化解一個人心中的怨恨；期盼在成百上千件事情上獲得榮耀，倒不如去避免做出一件不光彩的醜事。","analysis":"【訓詁與名物】「邀」在這裡是求取、博取之意；「歡」指歡心、喜悅；「釋」有解開、消除的意思；「怨」即怨恨。「希」是希望、期盼；「免」是避免、免除；「醜」指羞恥、不光彩的事端。\\\\n【章法與結構】本段使用了極為工整的對偶句法，「邀千百人之歡」對「希千百事之榮」，「不如釋一人之怨」對「不如免一事之醜」。透過「千百」與「一」的數量對比，以及「不如」的轉折，強烈凸顯出避惡化怨的重要性，語氣斬釘截鐵。\\\\n【思想與義理】此句反映了傳統文化中「防微杜漸」與「慎獨」的自省精神。建立好名聲或好人緣固然困難，但一旦有了怨恨或醜事，其破壞力往往遠大於無數的功勞。這提醒世人，在修身立業的過程中，與其盲目追求表面的光鮮亮麗與虛榮，不如腳踏實地，謹言慎行，以不結怨、不犯錯為根本底線。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-58","chapterId":"cai-gen-tan_ch-1","order":58,"canonicalText":"落落者，難合亦難分；欣欣者，易親亦易散。是以君子寧以剛方見憚，毋以媚悅取容。","sentenceIds":["cai-gen-tan_ch-1_p-58_s-1","cai-gen-tan_ch-1_p-58_s-2","cai-gen-tan_ch-1_p-58_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"性格孤高耿直的人，雖然難以與人投契相合，但一旦結交也極難分離；態度熱情迎合的人，雖然容易與人親近，但也很容易輕易散夥。因此君子寧可因為剛正不阿而讓人敬畏忌憚，也絕不通過諂媚迎合來討好世人。","analysis":"【題解與背景】\\\\n本段選自《菜根譚》〈修身〉第 58 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「落落者難合亦難分欣欣者易親亦易散是以君子……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「落」、「落」、「者」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《菜根譚》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：cai-gen-tan_ch-1_p-58）。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-59","chapterId":"cai-gen-tan_ch-1","order":59,"canonicalText":"意氣與天下相期，如春風之鼓暢庶類，不宜存半點隔閡之形；肝膽與天下相照，似秋月之洞徹羣品，不可作一毫曖昧之狀。","sentenceIds":["cai-gen-tan_ch-1_p-59_s-1","cai-gen-tan_ch-1_p-59_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"個人的襟懷抱負應當與天下人坦誠相待，就如同溫慢的春風吹拂、催生萬物成長一般，不應當存有半點隔閡與冷漠；自己的赤子肝膽應當與天下人坦白相照，就如同秋夜的明月清澈照亮萬物一般，絕對不能有絲毫含糊曖昧、不可告人的行徑。","analysis":"【主題與背景】本篇以「春風之鼓暢庶類」與「秋月之洞徹羣品」為喻，描繪了君子對待天下人時應有的光明磊落與廣闊胸襟。君子的意氣應當像春風般溫暖無私，包容感化一切眾生，消解任何心理隔閡；君子的心跡應當如秋月般皎潔無瑕，坦坦蕩蕩，沒有絲毫自私、陰暗與曖昧之處。\\\\n【詞義與名物】這體現了儒家「大公無私」與「光明磊落」的最高人格理想。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-60","chapterId":"cai-gen-tan_ch-1","order":60,"canonicalText":"仕途雖赫奕，常思林下的風味，則權且之念自輕；世途雖紛華，常思泉下的光景，則利慾之心自淡。鴻未至先援弓，兔已亡再呼矢，總非當機作用；風息時休起浪，岸到處便離船，纔是了手工夫。","sentenceIds":["cai-gen-tan_ch-1_p-60_s-1","cai-gen-tan_ch-1_p-60_s-2","cai-gen-tan_ch-1_p-60_s-3","cai-gen-tan_ch-1_p-60_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"仕途雖然顯赫榮耀，若能時常想想隱居山林的和風趣味，那麼對權勢名利的執著自然就會減輕；世間生活雖然繁華喧囂，若能時常想想死後歸於黃泉的冷清光景，那麼追逐利慾的心思自然就會淡化。大雁還沒飛來就急忙拉弓，野兔已經逃走才呼喊拿箭，這都不是順應時機的正確做法；風平浪靜時不要無事生非，船到彼岸時就該果斷離船上岸，這才是善於收尾、功成身退的真功夫。","analysis":"【主題與背景】本篇分為前後兩段。前段教人利用「林下」與「泉下」的對比來消解對「仕途」與「世途」的執著，以出世的終極關懷（死亡與歸隱）來稀釋現世的權欲與利慾。\\\\n【詞義與名物】後段則探討行事時的「當機」與「了手」。\\\\n【思想與篇章】「鴻未至先援弓」是庸人自擾，「兔已亡再呼矢」是悔之已晚，皆非智者所為。而「風息休起浪」告誡世人勿無事生非，「岸到處便離船」則象徵佛教的「法尚應捨，何況非法」，勸誡人們在功成名就或目標達成之際，要懂得果斷抽身、功成身退。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-61","chapterId":"cai-gen-tan_ch-1","order":61,"canonicalText":"從熱鬧場中出幾句清冷言語，便掃除無限殺機；向寒微路上用一點赤熱心腸，自培植許多生意。隨緣便是遣緣，似舞蝶與飛花共適；順事自然無事，若滿月偕盂水同圓。","sentenceIds":["cai-gen-tan_ch-1_p-61_s-1","cai-gen-tan_ch-1_p-61_s-2","cai-gen-tan_ch-1_p-61_s-3","cai-gen-tan_ch-1_p-61_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在爭名奪利的喧囂場閤中，說出幾句冷靜清醒的透徹話語，便能掃除無數的爭端與禍患；在貧寒窘迫的逆境之路上，施予一份赤誠溫暖的愛心，自然能為他人培植出無窮的生機。順應因緣就是解脫因緣的束縛，如同飛舞的蝴蝶與落花共舞般怡然自得；順應世事自然能免於是非困擾，如同天上的滿月與盆中的清水一同呈現圓滿。","analysis":"【主題與背景】本條包含兩重意境。一是行善與警世的智慧：在盲目狂熱的利益爭奪中，冷靜的警醒之言能消解戾氣；在艱難困頓的環境中，真誠的關懷能播撒希望的種子。\\\\n【詞義與名物】二是隨緣與順應的禪宗心境：「隨緣便是遣緣」指不刻意逃避，在順應當下因緣中達到超脫，如同蝶與花共舞；「順事自然無事」則是不與客觀現實對抗，心如盂水般清澈，承接滿月的清輝，達到物我合一、圓融無礙的妙境。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-62","chapterId":"cai-gen-tan_ch-1","order":62,"canonicalText":"淡泊之守，須從濃艷場中試來；鎮定之操，還向紛紜境上勘過。不然操持未定，應用未圓，恐一臨機登壇，而上品禪師又成一下品俗士矣。","sentenceIds":["cai-gen-tan_ch-1_p-62_s-1","cai-gen-tan_ch-1_p-62_s-2","cai-gen-tan_ch-1_p-62_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"淡泊名利的操守，必須在繁華富貴的場閤中經受住考驗；沉著鎮定的氣度，還必須在紛亂複雜的處境中磨練過關。否則，如果內心的持守還不穩固，應對變局的能力還不圓融，恐怕一旦面臨考驗登上實戰舞臺，原本自命清高的上品禪師，又會墮落成一個庸俗的下品俗士了。","analysis":"【主題與背景】本篇強調修煉必須經受現實環境的檢驗，反對閉門造車式的空談。真正的「淡泊」不是因為接觸不到繁華而淡泊，而是在面對萬丈紅塵（「濃艷場」）時依然能不動心；真正的「鎮定」不是在無事時的安靜，而是在面臨危難變故（「紛紜境」）時依然能氣定神閒。\\\\n【詞義與名物】只有經歷過現實的洗禮，修行才是真實不虛的，否則一旦面臨誘惑或危機，虛假的修養便會瞬間崩潰（「上品禪師又成下品俗士」）。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-63","chapterId":"cai-gen-tan_ch-1","order":63,"canonicalText":"廉所以戒貪。我果不貪，又何必標一廉名，以來貪夫之側目。讓所以戒爭。我果不爭，又何必立一讓的，以致暴客之彎弓。","sentenceIds":["cai-gen-tan_ch-1_p-63_s-1","cai-gen-tan_ch-1_p-63_s-2","cai-gen-tan_ch-1_p-63_s-3","cai-gen-tan_ch-1_p-63_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"廉潔是用來警戒貪婪的。如果我確實沒有貪心，又何必特意樹立廉潔的名聲，以至於招來貪婪之人的嫉恨與側目？謙讓是用來戒除爭奪的。如果我確實毫無爭奪之心，又何必刻意立起一個謙讓的靶子，以至於引來強暴之人的彎弓射擊？","analysis":"【主題與背景】本篇體現了道家「大巧若拙，大成若缺」的無名境界。道德的最高境界是自然而然的實踐，而非刻意的標榜。\\\\n【詞義與名物】「廉」與「讓」本是極好的德行，但如果將其當作名牌去「標榜」或「立靶」，反而會形成一種對立面，招致貪夫的嫉恨（側目）與暴客的攻擊（彎弓）。\\\\n【思想與篇章】真正的無貪無爭，是不落痕跡、融入日常的，不需要藉助「廉名」與「讓的」來向世人炫耀，如此才能真正避禍並保全德行。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-64","chapterId":"cai-gen-tan_ch-1","order":64,"canonicalText":"無事常如有事時，提防纔可以彌意外之變；有事常如無事時，鎮定方可以消局中之危。","sentenceIds":["cai-gen-tan_ch-1_p-64_s-1","cai-gen-tan_ch-1_p-64_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在平安無事的時候，要經常保持如同面臨變故時的警惕，有了防備才可以弭平意外發生的變故；在發生事端的時候，要經常保持如同無事時的從容，保持鎮定才可以化解局勢中的危機。","analysis":"【訓詁與名物】「無事常如有事時」指在太平時局要心存憂患；「提防」即防備；「彌」有填補、平息之意。「消」為消除、化解；「局中」意指當前所處的環境或事件的發展過程。\\\\n【章法與結構】這是一組非常標準的錯綜對仗句。「無事」與「有事」相互交錯，「提防」對應「鎮定」，「彌意外之變」對應「消局中之危」。前後兩句在情境上形成強烈對比，卻在道理上相輔相成，結構嚴謹，節奏感極強。\\\\n【思想與義理】這段話蘊含了深邃的辯證法與處世智慧。「無事如有事」是儒家的憂患意識，強調居安思危，未雨綢繆，唯有防患於未然，方能應付突如其來的打擊。「有事如無事」則近乎道家或兵家的泰然自若，在危難中保持冷靜理智，不自亂陣腳，才是轉危為安的關鍵。兩者結合，展現了動靜皆宜的修養境界。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-65","chapterId":"cai-gen-tan_ch-1","order":65,"canonicalText":"處世而欲人感恩，便為斂怨之道；遇事而為人除害，即是導利之機。","sentenceIds":["cai-gen-tan_ch-1_p-65_s-1","cai-gen-tan_ch-1_p-65_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在世俗交往中如果施予恩惠卻渴望得到別人的感恩，這反而會成為招致怨恨的途徑；遇到事情時若能真心為他人排除禍害，這便是引導利益、成就彼此的契機。","analysis":"【主題與背景】本篇揭示了施恩待人的心態對結果的深遠影響。「施恩圖報」是一種功利性交換，不僅會給受恩者帶來心理負擔，而且一旦對方的回報未達預期，施恩者便會心生不滿，受恩者也會心生反感，好事反而變成了「斂怨之道」。\\\\n【詞義與名物】相反，若出於純粹的善意去「為人除害」，不求回報地解決他人的切身痛苦，反而會自然而然地帶來彼此利益的交融與和諧（「導利之機」）。\\\\n【思想與篇章】這符合佛家「三輪體空」的無相佈施精神。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-66","chapterId":"cai-gen-tan_ch-1","order":66,"canonicalText":"持身如泰山九鼎凝然不動，則愆尤自少；應事若流水落花悠然而逝，則趣味常多。","sentenceIds":["cai-gen-tan_ch-1_p-66_s-1","cai-gen-tan_ch-1_p-66_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"立身持己應當像泰山與九鼎般莊重沉穩、巍然不動，過失與指責自然就會減少；應對世事則應當像流水落花般悠然逝去、不留執著，生活的樂趣與情致自然就會增多。","analysis":"【主題與背景】本條將「持身」的剛毅沉穩與「應事」的柔順圓融完美結合。立身處世需要有堅定不移的原則與巍然不動的道德定力，如「泰山九鼎」，如此便不會隨波逐流，從而減少過失（愆尤）；但在面對具體的事務與世俗紛擾時，又需要有超然灑脫的態度，如「流水落花」般順其自然、不事強求，不把煩惱留存於心，如此便能體會到生活的無窮趣味。\\\\n【詞義與名物】這體現了儒家的剛健中正與道家的隨順超脫。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-67","chapterId":"cai-gen-tan_ch-1","order":67,"canonicalText":"君子嚴如介石而畏其難親，鮮不以明珠為怪物而起按劍之心；小人滑如脂膏而喜其易合，鮮不以毒螫為甘飴而縱染指之慾。","sentenceIds":["cai-gen-tan_ch-1_p-67_s-1","cai-gen-tan_ch-1_p-67_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"君子如果性格過於嚴厲古板如頑石，讓人畏懼而難以親近，世人就很容易將這顆明珠誤視為怪物，從而心生警惕、按劍防備；小人如果狡猾諂媚如油脂般滑順，讓人因其容易逢迎而心生歡喜，世人就很容易將這種劇毒的螫刺當作甘甜的糖漿，從而放縱自己貪求的慾望。","analysis":"【主題與背景】本篇運用強烈的對比與典故，剖析了世人在對待君子與小人時常犯的心理錯誤。君子操守剛正，但若表現得過於嚴厲冰冷（「嚴如介石」），世人便會因產生隔閡而心生疑懼，甚至「按劍相眄」（典出鄒陽《獄中上樑王書》，指無端把寶珠投給路人，路人都會握劍防備），把好人當壞人。\\\\n【詞義與名物】小人擅長諂媚迎合（「滑如脂膏」），極易討人歡心，世人便會喪失警惕，將禍患當作恩惠（「以毒螫為甘飴」），引火自焚。\\\\n【思想與篇章】這警示君子要和藹可親、圓融待人，同時告誡世人防範小人的甜言蜜語。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-68","chapterId":"cai-gen-tan_ch-1","order":68,"canonicalText":"遇事只一味鎮定從容，縱紛若亂絲，終當就緒；待人無半毫矯偽欺隱，雖狡如山鬼，亦自獻誠。","sentenceIds":["cai-gen-tan_ch-1_p-68_s-1","cai-gen-tan_ch-1_p-68_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"遇到事情只要始終保持鎮定與從容，即使局勢繁雜得如同亂絲，最終也一定能理出頭緒；對待他人沒有絲毫的虛偽裝飾與欺騙隱瞞，即使對方像山鬼般狡詐多端，最終也會被你的赤誠所感化而主動獻出真誠。","analysis":"【主題與背景】本條闡述了處事的「鎮定」功夫與待人的「真誠」力量。面對亂局，急躁只會把事情弄得更糟，唯有沉著冷靜才能抽絲剝繭、化繁為簡（「縱紛若亂絲，終當就緒」）。\\\\n【詞義與名物】而在人際交往中，真誠是破解一切心防與陰謀的終極武器；以心換心，即便是最狡猾多疑的人（「狡如山鬼」），也會在純粹無偽的真誠面前放下戒備，化敵為友。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-69","chapterId":"cai-gen-tan_ch-1","order":69,"canonicalText":"肝腸煦若春風，雖囊乏一文，還憐煢獨；氣骨清如秋水，縱家徒四壁，終傲王公。","sentenceIds":["cai-gen-tan_ch-1_p-69_s-1","cai-gen-tan_ch-1_p-69_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"心腸像春風般溫暖慈祥，即使口袋裡不名一文，依然會去憐憫同情孤苦無依的人；氣節傲骨像秋水般清澈高潔，即使家裡窮得只剩四面牆壁，也依然敢於在王公貴族面前保持尊嚴與傲骨。","analysis":"【主題與背景】本篇讚美了士人理想的兩種崇高精神面貌：極致的慈悲與不妥協的傲骨。前半句「肝腸煦若春風」體現了儒家的仁愛精神，真正的善良與貧富無關，即便自身貧困，依然懷抱悲憫之心關懷弱者；後半句「氣骨清如秋水」則展現了道家與隱逸士人的獨立人格，面對強權富貴（「王公」）不諂媚、不屈服，以清貧自守為傲。\\\\n【詞義與名物】這正是「貧賤不能移，威武不能屈」的生動寫照。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-70","chapterId":"cai-gen-tan_ch-1","order":70,"canonicalText":"趨炎附勢之禍，甚慘亦甚速；棲恬守淡之趣，最濃亦最長。","sentenceIds":["cai-gen-tan_ch-1_p-70_s-1","cai-gen-tan_ch-1_p-70_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"攀附權貴、巴結勢力所帶來的禍害，不僅非常悲慘，而且來得非常迅速；安於寧靜、堅守淡泊所得到的樂趣，不僅最為深厚，而且能夠維持得最為長久。","analysis":"【訓詁與名物】「趨炎附勢」指奉承依附有權勢的人，其中「炎」比喻權勢顯赫；「慘」指悲慘、淒慘；「速」指快速。「棲恬守淡」指安於恬靜平淡的生活，不慕名利；「濃」指趣味濃厚；「長」指歷時長久。\\\\n【章法與結構】本段以正反對比的手法構成對偶。「趨炎附勢」與「棲恬守淡」一反一正，形成強烈反差；「甚慘亦甚速」與「最濃亦最長」在句式上完全對稱，從程度（慘/濃）與時間（速/長）兩個維度進行對照，論述條理分明，說服力強。\\\\n【思想與義理】此句批判了世俗名利場中攀附權貴的短視與危險，強調了淡泊明志的可貴。權勢如過眼雲煙，依附於此往往伴隨極大的政治或人際風險，一旦失勢便會迅速遭遇橫禍。相對地，能夠保持內心寧靜、不過分追求物質與虛名的人，才能體會到生命深層的悠長趣味。這是典型的道家崇尚自然與隱逸精神的體現。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-71","chapterId":"cai-gen-tan_ch-1","order":71,"canonicalText":"解鬥者助之以威，則怒氣自平；懲貪者濟之以欲，則利心反淡。所謂因其勢而利導之，亦救時應變一權宜法也。","sentenceIds":["cai-gen-tan_ch-1_p-71_s-1","cai-gen-tan_ch-1_p-71_s-2","cai-gen-tan_ch-1_p-71_s-3"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"調解他人爭鬥時，若能藉助威嚴法紀加以震懾，爭鬥雙方的怒氣自然就會平息；懲治貪婪之人時，若能故意滿足其部分慾望使其物極必反，其貪得無厭的念頭反而會逐漸冷淡。這就是所謂的因勢利導，也是救世應變的一種靈活權宜之策。","analysis":"【主題與背景】本條探討「因勢利導」的社會治理與心理調節智慧。調解爭鬥若只靠勸說往往無效，必須引入具有威懾力的力量（威），使雙方回歸理性；對治貪婪，若一味強行禁止，反而會激起更強的索求欲，有時採取「濟之以欲」（如老子所說的「將欲奪之，必固予之」，或者使其欲望飽和而產生厭倦）的反向操作，反而能使貪心平息。\\\\n【詞義與名物】這種以退為進、順應人性的方法，是解決複雜社會問題的辯證權宜之法。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-72","chapterId":"cai-gen-tan_ch-1","order":72,"canonicalText":"市恩不如報德之為厚。雪忿不若忍恥之為高。要譽不如逃名之為適。矯情不若直節之為真。","sentenceIds":["cai-gen-tan_ch-1_p-72_s-1","cai-gen-tan_ch-1_p-72_s-2","cai-gen-tan_ch-1_p-72_s-3","cai-gen-tan_ch-1_p-72_s-4"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"施恩討好以收買人心，不如真誠地回報他人恩德來得深厚；千方百計雪恥復仇，不如忍辱負重來得高尚；刻意逢迎博取名譽，不如躲避虛名來得舒適自在；違背常理裝腔作勢，不如保持剛直的節操來得真實純粹。","analysis":"【主題與背景】本篇通過四組對比，提倡返璞歸真、求真務實的道德修養。「市恩」（買弄恩惠、沽名釣譽）是虛偽的，而「報德」是真誠的；「雪忿」（報復洩憤）是狹隘的，而「忍恥」（忍辱負重）展現了極大的格局；「要譽」（追求名譽）會讓人套上枷鎖，而「逃名」才能獲得心靈的自由；「矯情」（虛偽做作）是扭曲的，而「直節」（剛直坦蕩）才是本真的顯現。\\\\n【詞義與名物】這引導人們捨棄虛飾，回歸真實的人格本色。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}},{"id":"cai-gen-tan_ch-1_p-73","chapterId":"cai-gen-tan_ch-1","order":73,"canonicalText":"救既敗之事者，如馭臨崖之馬，休輕策一鞭；圖垂成之功者，如挽上灘之舟，莫少停一棹。","sentenceIds":["cai-gen-tan_ch-1_p-73_s-1","cai-gen-tan_ch-1_p-73_s-2"],"sourceRefs":[{"label":"《菜根譚》—中國哲學書電子化計劃","edition":"明萬曆本《菜根譚》校本","location":"https://ctext.org/cai-gen-tan/zh","accessedAt":"2026-08-31"},{"label":"《菜根譚》—維基文庫","edition":"三臺館本《菜根譚》","location":"https://zh.wikisource.org/zh-hant/菜根譚","accessedAt":"2026-08-31"}],"readingAid":{"translation":"挽救已經面臨失敗的事情，如同駕馭著站在懸崖邊上的驚馬，千萬不能輕易抽打一鞭；謀求即將大功告成的事情，如同拉著正在逆流上灘的船隻，千萬不能稍微停下槳舵。","analysis":"【主題與背景】本條以極為形象的比喻，總結了做事在不同階段的應對策略。對於「既敗之事」（陷入危機的殘局），局勢已極起脆弱，任何盲目、魯莽的舉動（「輕策一鞭」）都可能導致徹底崩盤，因此必須小心翼翼、如履薄冰；而對於「垂成之功」（即將成功的關鍵時刻），如同逆水行舟，正處於最喫力的關頭，稍有鬆懈（「少停一棹」）就會前功盡棄，因此必須一鼓作氣、堅持到底。\\\\n【詞義與名物】這對指導人們處理危機與把握成功具有極高的實踐意義。\\\\n【思想與篇章】《菜根譚》融會儒釋道三家智慧，兼具操守堅定與處事圓融。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"cai-gen-tan_ch-1_p-1_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-1","order":1,"canonicalText":"餘過古剎，於殘經敗紙中拾得《菜根譚》一錄。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-1_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-1","order":2,"canonicalText":"翻視之，雖屬禪宗，然於身心性命之學，實有隱隱相發明者。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-1_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-1","order":3,"canonicalText":"亟攜歸，重加校讎，繕寫成帙。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-1_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-1","order":4,"canonicalText":"舊有序，文不雅馴，且於是書無關涉語，故芟之。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-1_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-1","order":5,"canonicalText":"著是書者為洪應明，究不知其為何許人也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-2_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-2","order":1,"canonicalText":"乾隆五十九年二月二日，遂初堂主人識","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-3_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-3","order":1,"canonicalText":"欲做精金美玉的人品，定從烈火中煆來；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-3_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-3","order":2,"canonicalText":"思立掀天揭地的事功，須向薄冰上履過。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-4_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-4","order":1,"canonicalText":"一念錯，便覺百行皆非，防之當如渡海浮囊，勿容一針之罅漏；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-4_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-4","order":2,"canonicalText":"萬善全，始得一生無愧。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-4_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-4","order":3,"canonicalText":"修之當如凌雲寶樹，須假眾木以撐持。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-5_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-5","order":1,"canonicalText":"忙處事為，常向閒中先檢點，過舉自稀。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-5_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-5","order":2,"canonicalText":"動時念想，預從靜裏密操持，非心自息。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-6_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-6","order":1,"canonicalText":"為善而欲自高勝人，施恩而欲要名結好，修業而欲驚世駭俗，植節而欲標異見奇，此皆是善念中戈矛，理路上荊棘，最易夾帶，最難拔除者也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-6_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-6","order":2,"canonicalText":"須是滌盡渣滓，斬絕萌芽，纔見本來真體。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-7_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-7","order":1,"canonicalText":"能輕富貴，不能輕一輕富貴之心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-7_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-7","order":2,"canonicalText":"能重名義，又復重一重名義之念。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-7_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-7","order":3,"canonicalText":"是事境之塵氛未掃，而心境之芥蒂未忘。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-7_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-7","order":4,"canonicalText":"此處拔除不凈，恐石去而草復生矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-8_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-8","order":1,"canonicalText":"紛擾固溺志之場，而枯寂亦槁心之地。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-8_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-8","order":2,"canonicalText":"故學者當棲心元默，以寧吾真體。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-8_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-8","order":3,"canonicalText":"亦當適志恬愉，以養吾圓機。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-9_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-9","order":1,"canonicalText":"昨日之非不可留，留之則根燼復萌，而塵情終累乎理趣；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-9_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-9","order":2,"canonicalText":"今日之是不可執，執之則渣滓未化，而理趣反轉為欲根。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-10_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-10","order":1,"canonicalText":"無事便思有閑雜念想否。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-10_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-10","order":2,"canonicalText":"有事便思有粗浮意氣否。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-10_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-10","order":3,"canonicalText":"得意便思有驕矜辭色否。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-10_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-10","order":4,"canonicalText":"失意便思有怨望情懷否。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-10_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-10","order":5,"canonicalText":"時時檢點，到得從多入少、從有入無處，纔是學問的真消息。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-11_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-11","order":1,"canonicalText":"士人有百折不回之真心，纔有萬變不窮之妙用。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-11_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-11","order":2,"canonicalText":"立業建功，事事要從實地著腳，若少慕聲聞，便成偽果；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-11_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-11","order":3,"canonicalText":"講道修德，念念要從虛處立基，若稍計功效，便落塵情。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-12_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-12","order":1,"canonicalText":"身不宜忙，而忙於閒暇之時，亦可儆惕惰氣；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-12_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-12","order":2,"canonicalText":"心不可放，而放於收攝之後，亦可鼓暢天機。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-13_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-13","order":1,"canonicalText":"鐘鼓體虛，為聲聞而招擊撞；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-13_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-13","order":2,"canonicalText":"麋鹿性逸，因豢養而受羈糜。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-13_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-13","order":3,"canonicalText":"可見名為招禍之本，欲乃散志之媒。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-13_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-13","order":4,"canonicalText":"學者不可不力為掃除也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-14_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-14","order":1,"canonicalText":"一念常惺，纔避去神弓鬼矢；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-14_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-14","order":2,"canonicalText":"纖塵不染，方解開地網天羅。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-15_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-15","order":1,"canonicalText":"一點不忍的念頭，是生民生物之根芽；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-15_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-15","order":2,"canonicalText":"一段不為的氣節，是撐天撐地之柱石。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-15_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-15","order":3,"canonicalText":"故君子於一蟲一蟻不忍傷殘，一縷一絲勿容貪冒，變可為萬物立命、天地立心矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-16_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-16","order":1,"canonicalText":"撥開世上塵氛，胸中自無火焰冰競；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-16_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-16","order":2,"canonicalText":"消卻心中鄙吝，眼前時有月到風來。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-17_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-17","order":1,"canonicalText":"學者動靜殊操、喧寂異趣，還是鍛煉未熟，心神混淆故耳。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-17_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-17","order":2,"canonicalText":"須是操存涵養，定雲止水中，有鳶飛魚躍的景象；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-17_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-17","order":3,"canonicalText":"風狂雨驟處，有波恬浪靜的風光，纔見處一化齊之妙。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-18_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-18","order":1,"canonicalText":"心是一顆明珠。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-18_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-18","order":2,"canonicalText":"以物慾障蔽之，猶明珠而混以泥沙，其洗滌猶易；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-18_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-18","order":3,"canonicalText":"以情識襯貼之，猶明珠而飾以銀黃，其洗滌最難。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-18_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-18","order":4,"canonicalText":"故學者不患垢病，而患潔病之難治；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-18_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-18","order":5,"canonicalText":"不畏事障，而畏理障之難除。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-19_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-19","order":1,"canonicalText":"軀殼的我要看得破，則萬有皆空而其心常虛，虛則義理來居；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-19_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-19","order":2,"canonicalText":"性命的我要認得真，則萬理皆備而其心常實，實則物慾不入。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-20_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-20","order":1,"canonicalText":"面上掃開十層甲，眉目纔無可憎；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-20_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-20","order":2,"canonicalText":"胸中滌去數鬥塵，語言方覺有味。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-21_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-21","order":1,"canonicalText":"完得心上之本來，方可言了心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-21_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-21","order":2,"canonicalText":"盡得世間之常道，纔堪論出世。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-22_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-22","order":1,"canonicalText":"我果為洪爐大冶，何患頑金鈍鐵之不可陶熔。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-22_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-22","order":2,"canonicalText":"我果為巨海長江，何患橫流污瀆之不能容納。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-23_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-23","order":1,"canonicalText":"白日欺人，難逃清夜之鬼報；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-23_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-23","order":2,"canonicalText":"紅顏失志，空貽皓首之悲傷。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-24_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-24","order":1,"canonicalText":"以積貨財之心積學問，以求功名之念求道德，以愛妻子之心愛父母，以保爵位之策保國家，出此入彼，念慮只差毫末，而超凡入聖，人品且判星淵矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-24_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-24","order":2,"canonicalText":"人胡不猛然轉念哉！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-25_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-25","order":1,"canonicalText":"立百福之基，只在一念慈祥；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-25_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-25","order":2,"canonicalText":"開萬善之門，無如寸心挹損。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-26_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-26","order":1,"canonicalText":"塞得物慾之路，才堪闢道義之門；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-26_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-26","order":2,"canonicalText":"馳得塵俗之肩，方可挑聖賢之擔。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-27_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-27","order":1,"canonicalText":"容得性情上偏私，便是一大學問；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-27_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-27","order":2,"canonicalText":"消得家庭內嫌雪，纔為火內栽蓮。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-28_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-28","order":1,"canonicalText":"事理因人言而悟者，有悟還有迷，總不如自悟之了了；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-28_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-28","order":2,"canonicalText":"意興從外境而得者，有得還有失，總不如自得之休休。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-29_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-29","order":1,"canonicalText":"情之同處即為性，舍情則性不可見，欲之公處即為理，舍欲則理不可明。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-29_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-29","order":2,"canonicalText":"故君子不能滅情，惟事平情而已；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-29_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-29","order":3,"canonicalText":"不能絕欲，惟期寡慾而已。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-30_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-30","order":1,"canonicalText":"欲遇變而無倉忙，須向常時念念守得定；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-30_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-30","order":2,"canonicalText":"欲臨死而無貪戀，須向生時事事看得輕。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-31_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-31","order":1,"canonicalText":"一念過差，足喪生平之善；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-31_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-31","order":2,"canonicalText":"終身檢飭，難蓋一事之愆。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-32_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-32","order":1,"canonicalText":"從五更枕蓆上參勘心體，氣未動，情未萌，纔見本來面目；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-32_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-32","order":2,"canonicalText":"向三時飲食中諳練世味，濃不欣，淡不厭，方為切實工夫。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-33_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-33","order":1,"canonicalText":"操存要有真宰，無真宰則遇事便倒，何以植頂天立地之砥柱！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-33_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-33","order":2,"canonicalText":"應用要有圓機，無圓機則觸物有礙，何以成旋乾轉坤之經綸！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-34_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-34","order":1,"canonicalText":"士君子之涉世，於人不可輕為喜怒，喜怒輕，則心腹肝膽皆為人所窺；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-34_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-34","order":2,"canonicalText":"於物不可重為愛憎，愛憎重，則意氣精神悉為物所制。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-35_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-35","order":1,"canonicalText":"倚高才而玩世，背後須防射影之蟲；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-35_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-35","order":2,"canonicalText":"飾厚貌以欺人，面前恐有照膽之鏡。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-36_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-36","order":1,"canonicalText":"心體澄徹，常在明鏡止水之中，則天下自無可厭之事；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-36_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-36","order":2,"canonicalText":"意氣和平，賞在麗日光風之內，則天下自無可惡之人。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-36_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-36","order":3,"canonicalText":"當是非邪正之交，不可少遷就，少遷就則失從違之正；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-36_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-36","order":4,"canonicalText":"值利害得失之會，不可太分明，太分明則起趨避之私。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-37_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-37","order":1,"canonicalText":"蒼蠅附驥，捷則捷矣，難辭處後之羞；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-37_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-37","order":2,"canonicalText":"蘿蔦依松，高則高矣，未免仰攀之恥。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-37_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-37","order":3,"canonicalText":"所以君子寧以風霜自挾，毋為魚鳥親人。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-38_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-38","order":1,"canonicalText":"好醜心太明，則物不契；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-38_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-38","order":2,"canonicalText":"賢愚心太明，則人不親。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-38_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-38","order":3,"canonicalText":"士君子須是內精明而外渾厚，使好醜兩得其平，賢愚共受其益，纔是生成的德量。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-39_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-39","order":1,"canonicalText":"伺察以為明者，常因明而生暗，故君子以恬養智；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-39_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-39","order":2,"canonicalText":"奮迅以為速者，多因速度而致遲，故君子以重持輕。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-39_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-39","order":3,"canonicalText":"士君子濟人利物，宜居其實，不宜居其名，居其名則德損；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-39_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-39","order":4,"canonicalText":"士大夫憂國為民，當有其心，不當有其語，有其語則毀來。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-40_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-40","order":1,"canonicalText":"遇大事矜持者，小事必縱弛；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-40_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-40","order":2,"canonicalText":"處明庭檢飾者，暗室必放逸。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-40_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-40","order":3,"canonicalText":"君子只是一個念頭持到底，自然臨小事如臨大敵，坐密室若坐通衢。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-41_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-41","order":1,"canonicalText":"使人有面前之譽，不若使其無背後之毀；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-41_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-41","order":2,"canonicalText":"使人有乍交之歡，不若使其無久處之厭。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-42_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-42","order":1,"canonicalText":"善啟迪人心者，當因其所明而漸通之，毋強開其所閉；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-42_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-42","order":2,"canonicalText":"善移風化者，當因其所易而漸及之，毋輕矯其所難。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-43_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-43","order":1,"canonicalText":"彩筆描空，筆不落色，而空亦不受染；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-43_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-43","order":2,"canonicalText":"利刀割水，刀不損鍔，而水亦不留痕。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-43_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-43","order":3,"canonicalText":"得此意以持身涉世，感與應俱適，心與境兩忘矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-44_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-44","order":1,"canonicalText":"己之情慾不可縱，當用逆之之法以制之，其道只在一忍字；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-44_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-44","order":2,"canonicalText":"人之情慾不可拂，當用順之之法以調之，其道只在一恕字。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-44_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-44","order":3,"canonicalText":"今人皆恕以適己而忍以制人，毋乃不可乎！","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-45_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-45","order":1,"canonicalText":"好察非明，能察能不察之謂明；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-45_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-45","order":2,"canonicalText":"必勝非勇，能勝能不勝之謂勇。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-46_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-46","order":1,"canonicalText":"隨時之內善救時，若和風之消酷暑；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-46_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-46","order":2,"canonicalText":"混俗之中能脫俗，似淡月之映輕雲。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-47_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-47","order":1,"canonicalText":"思入世而有為者，須先領得世外風光，否則無以脫垢濁之塵緣；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-47_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-47","order":2,"canonicalText":"思出世而無染者，須先諳盡世中滋味。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-47_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-47","order":3,"canonicalText":"否則無以持空寂之後苦趣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-48_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-48","order":1,"canonicalText":"與人者，與其易疏於終，不若難親於始；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-48_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-48","order":2,"canonicalText":"御事者，與其巧持於後，不若拙守於前。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-49_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-49","order":1,"canonicalText":"酷烈之禍，多起於翫忽之人；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-49_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-49","order":2,"canonicalText":"盛滿之功，常敗於細微之事。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-49_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-49","order":3,"canonicalText":"故語雲：「人人道好，須防一人著腦；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-49_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-49","order":4,"canonicalText":"事事有功，須防一事不終。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-49_s-5","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-49","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-50_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-50","order":1,"canonicalText":"功名富貴，直從滅處觀究竟，則貪戀自輕；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-50_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-50","order":2,"canonicalText":"橫逆困窮，直從起處究由來，則怨尤自息。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-51_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-51","order":1,"canonicalText":"宇宙內事要力擔當，又要善擺脫。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-51_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-51","order":2,"canonicalText":"不擔當，則無經世之事業；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-51_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-51","order":3,"canonicalText":"不擺脫，則無出世之襟期。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-52_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-52","order":1,"canonicalText":"待人而留有餘，不盡之恩禮，則可以維繫無厭之人心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-52_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-52","order":2,"canonicalText":"御事而留有餘，不盡之才智，則可以提防不測之事變。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-53_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-53","order":1,"canonicalText":"了心自了事，猶根拔而草不生；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-53_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-53","order":2,"canonicalText":"逃世不逃名，似羶存蚋而仍集。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-54_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-54","order":1,"canonicalText":"仇邊之弩易避，而恩裏之戈難防；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-54_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-54","order":2,"canonicalText":"苦時之坎易逃，而樂處之阱難脫。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-55_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-55","order":1,"canonicalText":"羶穢則蠅蚋叢嘬，芳馨則蜂蝶交侵。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-55_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-55","order":2,"canonicalText":"故君子不作垢業，亦不立芳名。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-55_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-55","order":3,"canonicalText":"只是元氣渾然，圭角不露，便是持身涉世一安樂窩也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-56_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-56","order":1,"canonicalText":"從靜中觀物動，向閒處看人忙，纔得超塵脫俗的趣味；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-56_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-56","order":2,"canonicalText":"遇忙處會偷閒，處鬧中能取靜，便是安身立命的工夫。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-57_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-57","order":1,"canonicalText":"邀千百人之歡，不如釋一人之怨；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-57_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-57","order":2,"canonicalText":"希千百事之榮，不如免一事之醜。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-58_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-58","order":1,"canonicalText":"落落者，難合亦難分；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-58_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-58","order":2,"canonicalText":"欣欣者，易親亦易散。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-58_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-58","order":3,"canonicalText":"是以君子寧以剛方見憚，毋以媚悅取容。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-59_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-59","order":1,"canonicalText":"意氣與天下相期，如春風之鼓暢庶類，不宜存半點隔閡之形；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-59_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-59","order":2,"canonicalText":"肝膽與天下相照，似秋月之洞徹羣品，不可作一毫曖昧之狀。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-60_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-60","order":1,"canonicalText":"仕途雖赫奕，常思林下的風味，則權且之念自輕；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-60_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-60","order":2,"canonicalText":"世途雖紛華，常思泉下的光景，則利慾之心自淡。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-60_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-60","order":3,"canonicalText":"鴻未至先援弓，兔已亡再呼矢，總非當機作用；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-60_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-60","order":4,"canonicalText":"風息時休起浪，岸到處便離船，纔是了手工夫。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-61_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-61","order":1,"canonicalText":"從熱鬧場中出幾句清冷言語，便掃除無限殺機；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-61_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-61","order":2,"canonicalText":"向寒微路上用一點赤熱心腸，自培植許多生意。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-61_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-61","order":3,"canonicalText":"隨緣便是遣緣，似舞蝶與飛花共適；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-61_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-61","order":4,"canonicalText":"順事自然無事，若滿月偕盂水同圓。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-62_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-62","order":1,"canonicalText":"淡泊之守，須從濃艷場中試來；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-62_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-62","order":2,"canonicalText":"鎮定之操，還向紛紜境上勘過。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-62_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-62","order":3,"canonicalText":"不然操持未定，應用未圓，恐一臨機登壇，而上品禪師又成一下品俗士矣。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-63_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-63","order":1,"canonicalText":"廉所以戒貪。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-63_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-63","order":2,"canonicalText":"我果不貪，又何必標一廉名，以來貪夫之側目。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-63_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-63","order":3,"canonicalText":"讓所以戒爭。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-63_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-63","order":4,"canonicalText":"我果不爭，又何必立一讓的，以致暴客之彎弓。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-64_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-64","order":1,"canonicalText":"無事常如有事時，提防纔可以彌意外之變；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-64_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-64","order":2,"canonicalText":"有事常如無事時，鎮定方可以消局中之危。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-65_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-65","order":1,"canonicalText":"處世而欲人感恩，便為斂怨之道；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-65_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-65","order":2,"canonicalText":"遇事而為人除害，即是導利之機。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-66_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-66","order":1,"canonicalText":"持身如泰山九鼎凝然不動，則愆尤自少；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-66_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-66","order":2,"canonicalText":"應事若流水落花悠然而逝，則趣味常多。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-67_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-67","order":1,"canonicalText":"君子嚴如介石而畏其難親，鮮不以明珠為怪物而起按劍之心；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-67_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-67","order":2,"canonicalText":"小人滑如脂膏而喜其易合，鮮不以毒螫為甘飴而縱染指之慾。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-68_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-68","order":1,"canonicalText":"遇事只一味鎮定從容，縱紛若亂絲，終當就緒；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-68_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-68","order":2,"canonicalText":"待人無半毫矯偽欺隱，雖狡如山鬼，亦自獻誠。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-69_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-69","order":1,"canonicalText":"肝腸煦若春風，雖囊乏一文，還憐煢獨；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-69_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-69","order":2,"canonicalText":"氣骨清如秋水，縱家徒四壁，終傲王公。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-70_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-70","order":1,"canonicalText":"趨炎附勢之禍，甚慘亦甚速；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-70_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-70","order":2,"canonicalText":"棲恬守淡之趣，最濃亦最長。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-71_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-71","order":1,"canonicalText":"解鬥者助之以威，則怒氣自平；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-71_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-71","order":2,"canonicalText":"懲貪者濟之以欲，則利心反淡。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-71_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-71","order":3,"canonicalText":"所謂因其勢而利導之，亦救時應變一權宜法也。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-72_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-72","order":1,"canonicalText":"市恩不如報德之為厚。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-72_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-72","order":2,"canonicalText":"雪忿不若忍恥之為高。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-72_s-3","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-72","order":3,"canonicalText":"要譽不如逃名之為適。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-72_s-4","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-72","order":4,"canonicalText":"矯情不若直節之為真。","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-73_s-1","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-73","order":1,"canonicalText":"救既敗之事者，如馭臨崖之馬，休輕策一鞭；","chunks":[],"tags":[]},{"id":"cai-gen-tan_ch-1_p-73_s-2","workId":"cai-gen-tan","chapterId":"cai-gen-tan_ch-1","passageId":"cai-gen-tan_ch-1_p-73","order":2,"canonicalText":"圖垂成之功者，如挽上灘之舟，莫少停一棹。","chunks":[],"tags":[]}]}');export{a as default};
